/* Card set: IndyCar (generated from indy.csv by package_indy.py).
   (indy.js exceeds the push size limit, so the remaining cards live in indy-additions.js,
   which must stay directly after 'indy.js' in sets/manifest.js.) */
CardSets.register({"id":"indy","name":"IndyCar","code":"INDY","description":"500 cards of American open-wheel racing — the Indianapolis 500, its legends, its tracks and its machinery, from the Marmon Wasp to Álex Palou. Real photographs throughout.","theme":{"primary":"#8f2d26","secondary":"#17181c","artBackground":"#141114","artFit":"cover"},"pack":{"name":"IndyCar","emblem":"🏎️","skin":"indy"},"cards":[{"name":"A.J. Foyt","rarity":"chase","id":"a-j-foyt","subtitle":"Driver","details":"The first four-time Indianapolis 500 winner, in 1961, 1964, 1967 and 1977, Foyt started a record 35 consecutive 500s and won seven USAC titles.","image":"https://d2i8ejbvsgsqtt.cloudfront.net/gallery/indy/2015/20150112-b/med/1977-288-15-AJ-FOYT-PULLING-INTO-VC.jpg"},{"name":"Al Unser","rarity":"chase","id":"al-unser","subtitle":"Driver","details":"A four-time Indianapolis 500 winner in 1970, 1971, 1978 and 1987, Unser collected three national championships and 39 Indy car victories.","image":"https://static0.hotcarsimages.com/wordpress/wp-content/uploads/2021/06/Al-Unser-Sr-autoweek.jpg?q=50&fit=crop&w=825&dpr=1.5"},{"name":"Bobby Unser","rarity":"chase","id":"bobby-unser","subtitle":"Driver","details":"Unser won the Indianapolis 500 in three different decades, 1968, 1975 and 1981, along with two USAC national championships.","image":"https://motorsportmagazine.b-cdn.net/wp-content/uploads/2025/05/Bobby-Unser-1981-Indianapolis-500.jpg"},{"name":"Hélio Castroneves","rarity":"chase","id":"h-lio-castroneves","subtitle":"Driver","details":"Castroneves joined the four-time Indianapolis 500 winners club with victories in 2001, 2002, 2009 and 2021, a span of twenty years.","image":"https://frontstretch.com/wp-content/uploads/2023/05/Helio-Castroneves-Indianapolis-500-presented-by-Gainbridge_ReferenceImageWithoutWatermark_m42518.jpg"},{"name":"Mario Andretti","rarity":"chase","id":"mario-andretti","subtitle":"Driver","details":"Andretti won the 1969 Indianapolis 500 and three USAC titles, then took the 1978 Formula 1 world championship in a career spanning four decades.","image":"https://www.automoblog.com/wp-content/uploads/2017/05/imsc4698.jpg"},{"name":"Rick Mears","rarity":"chase","id":"rick-mears","subtitle":"Driver","details":"Mears won the Indianapolis 500 in 1979, 1984, 1988 and 1991, set a record with six Indy poles, and added three CART championships.","image":"https://daveblackphotography.com/wp-content/uploads/2014/12/138-Mears-Image-Rick-Mears-4-Time-INDY-500-Winner1.jpg"},{"name":"Scott Dixon","rarity":"chase","id":"scott-dixon","subtitle":"Driver","details":"Dixon won six IndyCar championships between 2003 and 2020, the 2008 Indianapolis 500, and led a record 665 laps in the 500 itself.","image":"https://1075thefan.com/wp-content/uploads/sites/100/2025/05/17470625943594.jpg?w=1024&strip=all&quality=80"},{"name":"Álex Palou","rarity":"chase","id":"lex-palou","subtitle":"Driver","details":"Palou won five IndyCar championships in 2021, 2023, 2024, 2025 and 2026, four of them consecutively, plus the 2025 Indianapolis 500.","image":"https://cdn-cs-images.racer.com/v3/assets/blte77f57883ea46be1/blt502086c336c3812c/69fe357473cbe30b2fee2f3f/Alex_Palou_-_Indianapolis_500_Open_Test_-_By_Paul_Hurley_Large_Image_Without_Watermark_m151270.jpg?environment=live&width=1200&height=630&fit=crop"},{"name":"Indianapolis Motor Speedway","rarity":"chase","id":"indianapolis-motor-speedway","subtitle":"Track & Race","details":"Opened in 1909 and home of the Indianapolis 500 since 1911, the 2.5-mile oval in Speedway, Indiana is nicknamed the Brickyard.","image":"https://www.saturdayeveningpost.com/wp-content/uploads/satevepost/2020-05-28-panasonic-pagoda-indianapolis-motor-speedway-shutterstock.jpg"},{"name":"The Indianapolis 500","rarity":"chase","id":"the-indianapolis-500","subtitle":"Moment","details":"First run in 1911, the race covers 200 laps and 500 miles at Indianapolis and anchors the Month of May on the IndyCar calendar.","image":"https://motorsportmagazine.b-cdn.net/wp-content/uploads/2021/06/Start-of-the-2021-Indy-500.jpg"},{"name":"Al Unser Jr.","rarity":"legendary","id":"al-unser-jr","subtitle":"Driver","details":"Unser Jr. won the Indianapolis 500 in 1992 by 0.043 seconds, the closest finish of its time, again in 1994, and took the 1990 CART title.","image":"assets/sets/compress/indy__al-unser-jr.webp"},{"name":"Arie Luyendyk","rarity":"legendary","id":"arie-luyendyk","subtitle":"Driver","details":"Luyendyk won the Indianapolis 500 in 1990 and 1997; his 1990 average speed record stood as the fastest 500 for more than two decades.","image":"https://cdn-cs-images.racer.com/v3/assets/blte77f57883ea46be1/blt4546fb69c161cc07/67d49db9fa4d9202858dfbc0/1990_arie_luyendyk.jpg?environment=live"},{"name":"Bill Vukovich","rarity":"legendary","id":"bill-vukovich","subtitle":"Driver","details":"Vukovich won back-to-back Indianapolis 500s in 1953 and 1954, then was killed in a crash while leading the 1955 race chasing a third straight.","image":"https://d2i8ejbvsgsqtt.cloudfront.net/gallery/indycar/indy/1953/19530101-nphotographer/med/imsc4334.jpg"},{"name":"Bobby Rahal","rarity":"legendary","id":"bobby-rahal","subtitle":"Driver","details":"Rahal won the 1986 Indianapolis 500 for Truesports and collected three CART championships, in 1986, 1987 and 1992, across a 17-year career.","image":"assets/sets/compress/indy__bobby-rahal.webp"},{"name":"Dan Wheldon","rarity":"legendary","id":"dan-wheldon","subtitle":"Driver","details":"Wheldon won the Indianapolis 500 in 2005 and the 2005 IndyCar title, then won the 2011 race by passing JR Hildebrand on the final corner.","image":"https://d2i8ejbvsgsqtt.cloudfront.net/gallery/indycar/homestead/2005/20050120-mvoorhees/med/0119_Whel_105.jpg"},{"name":"Dario Franchitti","rarity":"legendary","id":"dario-franchitti","subtitle":"Driver","details":"Franchitti won the Indianapolis 500 in 2007, 2010 and 2012 and four IndyCar championships, all with Ganassi and Andretti Green teams.","image":"https://mma.prnewswire.com/media/1245453/Dario_Franchitti.jpg?p=publish&w=950"},{"name":"Emerson Fittipaldi","rarity":"legendary","id":"emerson-fittipaldi","subtitle":"Driver","details":"Already a two-time Formula 1 world champion, Fittipaldi crossed to Indy cars and won the Indianapolis 500 in 1989 and again in 1993.","image":"https://i0.wp.com/www.vmax.si/wp-content/uploads/2021/05/Emerson-Fittipaldi.jpg?resize=660%2C495&ssl=1"},{"name":"Gordon Johncock","rarity":"legendary","id":"gordon-johncock","subtitle":"Driver","details":"Johncock won the Indianapolis 500 in 1973 and in 1982, when he held off a charging Rick Mears by just 0.16 seconds at the finish.","image":"https://www.motortrend.com/uploads/sites/11/2019/11/1982-stp-wildcat-indy-car-gordon-johncock.jpg"},{"name":"Jim Clark","rarity":"legendary","id":"jim-clark","subtitle":"Driver","details":"Clark won the 1965 Indianapolis 500 in Colin Chapman's rear-engined Lotus 38, the win that ended the front-engined roadster era at Indy.","image":"https://www.fia.com/sites/default/files/styles/content_details/public/indy196508.jpg?itok=cUsgSCeW"},{"name":"Johnny Rutherford","rarity":"legendary","id":"johnny-rutherford","subtitle":"Driver","details":"Rutherford won the Indianapolis 500 in 1974, 1976 and 1980, and in 1980 he paired the 500 victory with the CART championship.","image":"https://www.autoracing1.com/wp-content/uploads/historic/rutherfordindy1980.jpg"},{"name":"Josef Newgarden","rarity":"legendary","id":"josef-newgarden","subtitle":"Driver","details":"Newgarden won back-to-back Indianapolis 500s in 2023 and 2024 with last-lap passes, after IndyCar championships in 2017 and 2019.","image":"https://images2.minutemediacdn.com/image/upload/c_crop,x_0,y_0,w_4958,h_2788/c_fill,w_1440,ar_1440:810,f_auto,q_auto,g_auto/images/ImagnImages/mmsport/243/01hz549jnch0awejx71n.jpg"},{"name":"Juan Pablo Montoya","rarity":"legendary","id":"juan-pablo-montoya","subtitle":"Driver","details":"Montoya dominated the 2000 Indianapolis 500 as a rookie, leading 167 laps, won the 1999 CART title, and won the 500 again in 2015.","image":"https://motorsportmagazine.b-cdn.net/wp-content/uploads/2016/04/Juan-Pablo-Montoya_0.jpg"},{"name":"Louis Meyer","rarity":"legendary","id":"louis-meyer","subtitle":"Driver","details":"Meyer was the first driver to win the Indianapolis 500 three times, taking the race in 1928, 1933 and 1936 in the front-engined era.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/90/Louis_Meyer_at_the_1928_Indianapolis_500_%28cropped%29.jpg/500px-Louis_Meyer_at_the_1928_Indianapolis_500_%28cropped%29.jpg"},{"name":"Mauri Rose","rarity":"legendary","id":"mauri-rose","subtitle":"Driver","details":"Rose won the Indianapolis 500 in 1947 and 1948, and in 1941 he finished the race in relief for Floyd Davis after taking over Davis's car.","image":"https://upload.wikimedia.org/wikipedia/en/9/9e/Portrait_of_Mauri_Rose.jpg"},{"name":"Michael Andretti","rarity":"legendary","id":"michael-andretti","subtitle":"Driver","details":"Andretti won 42 CART races and the 1991 championship, and led 431 laps at Indianapolis, more than any driver who never won the 500.","image":"assets/sets/compress/indy__michael-andretti.webp"},{"name":"Rodger Ward","rarity":"legendary","id":"rodger-ward","subtitle":"Driver","details":"Ward won the Indianapolis 500 in 1959 and 1962 and two USAC titles, and lost the famous 1960 duel with Jim Rathmann by one position.","image":"https://d2i8ejbvsgsqtt.cloudfront.net/gallery/indycar/indy/1962/19620101-nphotographer/med/1962_Rodger_Ward_DA.jpg"},{"name":"Sam Hornish Jr.","rarity":"legendary","id":"sam-hornish-jr","subtitle":"Driver","details":"Hornish won IRL championships in 2001 and 2002, then a third in 2006, sealed by his last-lap pass on rookie Marco Andretti at Indianapolis.","image":"https://mrpitbox.com/wp-content/uploads/2026/05/GettyImages-71072648-BKaYHk.jpg"},{"name":"Sébastien Bourdais","rarity":"legendary","id":"s-bastien-bourdais","subtitle":"Driver","details":"Bourdais won four consecutive Champ Car championships from 2004 to 2007 and collected 37 wins in top-level American open-wheel racing.","image":"https://www.autoracing1.com/wp-content/uploads/historic/2005-long-beach-winner-sebastien-bourdais.jpg"},{"name":"Takuma Sato","rarity":"legendary","id":"takuma-sato","subtitle":"Driver","details":"Sato won the Indianapolis 500 in 2017 and 2020, becoming the first Japanese driver to win both an IndyCar race and the 500 itself.","image":"https://www.drivencarguide.co.nz/media/132685/16716278_10155151004823678_1652205990140916786_o.jpg"},{"name":"Ted Horn","rarity":"legendary","id":"ted-horn","subtitle":"Driver","details":"Horn won three consecutive AAA championships from 1946 to 1948 and strung together top-four finishes at Indianapolis without a 500 win.","image":"https://cdn-cs-images.racer.com/v3/assets/blte77f57883ea46be1/blt069e04254ba135b8/67e99aacac8b979dd62397e1/horn1939-2.jpg"},{"name":"Tommy Milton","rarity":"legendary","id":"tommy-milton","subtitle":"Driver","details":"Milton was the first driver to win the Indianapolis 500 twice, in 1921 and 1923, and added two AAA national championships.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/0b/Tommy_Milton_1921.jpg/1280px-Tommy_Milton_1921.jpg"},{"name":"Tony Kanaan","rarity":"legendary","id":"tony-kanaan","subtitle":"Driver","details":"Kanaan won the 2004 IRL championship and the 2013 Indianapolis 500, and set a record with 318 consecutive IndyCar starts.","image":"https://d2i8ejbvsgsqtt.cloudfront.net/gallery/indycar/stpete/2009/20090403-jhaines/med/12JH0590-2185.jpg"},{"name":"Wilbur Shaw","rarity":"legendary","id":"wilbur-shaw","subtitle":"Driver","details":"Shaw won the Indianapolis 500 in 1937, 1939 and 1940, then as Speedway president helped revive the race after the Second World War.","image":"https://indyencyclopedia.org/wp-content/uploads/2023/11/warren-wilbur-shaw-2-full.jpg"},{"name":"Will Power","rarity":"legendary","id":"will-power","subtitle":"Driver","details":"Power won the 2018 Indianapolis 500 and IndyCar championships in 2014 and 2022, and holds the series record for qualifying poles.","image":"https://speedcafe.b-cdn.net/wp-content/uploads/2025/09/Will-Power-Snap-On-Milwaukee-Mile-250-By_-Paul-Hurley_Large-Image-Without-Watermark_m141449.jpg"},{"name":"Grand Prix of Long Beach","rarity":"legendary","id":"grand-prix-of-long-beach","subtitle":"Track & Race","details":"Indy cars have headlined the streets of Long Beach, California since 1984, making it one of the longest-running street races in America.","image":"https://napaknowhowblo.wpengine.com/wp-content/uploads/2019/04/Alexander-Rossi-Long-Beach-2019-200-Wins-Andretti-Autosport-opening-laps.jpg"},{"name":"Milwaukee Mile","rarity":"legendary","id":"milwaukee-mile","subtitle":"Track & Race","details":"Racing at the Wisconsin State Fair Park oval dates to 1903, making the Milwaukee Mile one of the oldest operating speedways in the world.","image":"https://www.pitdebrief.com/wp-content/uploads/Rinus-VeeKay-Snap-On-Makers-and-Fixers-250-at-the-Milwaukee-Mile-By_-Joe-Skibinski_Ref-Image-Without-Watermark_m164267.jpg"},{"name":"Pocono Raceway","rarity":"legendary","id":"pocono-raceway","subtitle":"Track & Race","details":"Pocono's triangular 2.5-mile oval borrowed its three turns from Trenton, Indianapolis and Milwaukee, and hosted the Triple Crown Pocono 500.","image":"assets/sets/compress/indy__pocono-raceway.webp"},{"name":"A.J. Foyt's 35 Consecutive Starts","rarity":"legendary","id":"a-j-foyt-s-35-consecutive-starts","subtitle":"Moment","details":"Foyt started every Indianapolis 500 from 1958 through 1992, a run of 35 consecutive starts that remains the all-time record for the race.","image":"https://motorsportmagazine.b-cdn.net/wp-content/uploads/2014/07/AJ-Foyt-1977-Indianapolis-500-3.jpg"},{"name":"Borg-Warner Trophy","rarity":"legendary","id":"borg-warner-trophy","subtitle":"Moment","details":"Awarded since 1936, the sterling-silver Borg-Warner Trophy carries a sculpted likeness of every Indianapolis 500 winner's face.","image":"https://www.indycar.com/-/media/IndyCar/News/Standard/2025/05/05-24-Borg.jpg"},{"name":"The Andretti Family","rarity":"legendary","id":"the-andretti-family","subtitle":"Moment","details":"Mario Andretti won the 1969 Indianapolis 500, but Michael, Jeff, John and Marco never won it, a drought nicknamed the Andretti Curse.","image":"https://garagem360.com.br/wp-content/uploads/2019/08/michael_mario_marco_andretti3.jpg"},{"name":"The Unser Family","rarity":"legendary","id":"the-unser-family","subtitle":"Moment","details":"Bobby, Al and Al Unser Jr. won nine Indianapolis 500s between them, three, four and two apiece, the most by any single racing family.","image":"assets/sets/compress/indy__the-unser-family.webp"},{"name":"1965 Lotus 38","rarity":"legendary","id":"1965-lotus-38","subtitle":"Car & Era","details":"Driven by Jim Clark to victory in 1965, the Lotus 38 was the first rear-engined car to win the Indianapolis 500, changing Indy car design for good.","image":"https://motorsportmagazine.b-cdn.net/wp-content/uploads/2016/04/Lotus38.jpg"},{"name":"Penske PC-23 Mercedes 500I","rarity":"legendary","id":"penske-pc-23-mercedes-500i","subtitle":"Car & Era","details":"For 1994 Penske built a secret pushrod Mercedes 500I engine for a rules loophole, and Al Unser Jr. won the Indianapolis 500 with the PC-23.","image":"https://projetomotor.com.br/wp-content/uploads/2020/05/Penske-Unser-1994-DESTAQUE.jpg"},{"name":"Chip Ganassi Racing","rarity":"legendary","id":"chip-ganassi-racing","subtitle":"Team","details":"Ganassi's team became a modern powerhouse as the home of Scott Dixon's six championships and Alex Palou's five, with multiple 500 wins.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6f/Scott_Dixon_2011_Indy_Japan_300_Qualify.jpg/1280px-Scott_Dixon_2011_Indy_Japan_300_Qualify.jpg"},{"name":"Team Penske","rarity":"legendary","id":"team-penske","subtitle":"Team","details":"Team Penske set the owner's standard at Indianapolis with a record 20 Indianapolis 500 victories, from Mark Donohue in 1972 to 2024.","image":"https://www.speedsport-magazine.com/media/images/meldeliste/zoom1000/team-penske-dallara-dw12-chevrolet-power-58518.jpg"},{"name":"Alex Zanardi","rarity":"epic","id":"alex-zanardi","subtitle":"Driver","details":"Zanardi won back-to-back CART championships in 1997 and 1998, and his corkscrew pass on Bryan Herta at Laguna Seca in 1996 became legend.","image":"https://medias.blogbmw.fr/2026/05/1997-CART-Chip-Ganassi-Racing-Alex-Zanardi-1280x914.jpg"},{"name":"Alexander Rossi","rarity":"epic","id":"alexander-rossi","subtitle":"Driver","details":"Rossi won the 100th Indianapolis 500 in 2016 as a rookie, nursing his fuel over the final laps to beat teammate Carlos Munoz to the line.","image":"assets/sets/compress/indy__alexander-rossi.webp"},{"name":"Buddy Lazier","rarity":"epic","id":"buddy-lazier","subtitle":"Driver","details":"Lazier won the 1996 Indianapolis 500 during the first IRL season and added the 2000 IRL championship with Hemelgarn Racing.","image":"https://pbs.twimg.com/media/G4X20cgWYAAX3F2.jpg"},{"name":"Buddy Rice","rarity":"epic","id":"buddy-rice","subtitle":"Driver","details":"Rice won the rain-shortened 2004 Indianapolis 500 from pole position for Rahal Letterman Racing, capping a breakthrough month of May.","image":"https://d2i8ejbvsgsqtt.cloudfront.net/gallery/indycar/indy/2004/20040516-dedelstein/med/IMG_1171.jpg"},{"name":"Dan Gurney","rarity":"epic","id":"dan-gurney","subtitle":"Driver","details":"Gurney finished second, second and third at Indianapolis from 1968 to 1970 without winning, while his Eagle chassis became an Indy standard.","image":"https://images.ctfassets.net/lmiyf1b7ib63/11674_featured_image/9eab0858dbcfd2d56bc2ea627ad20482/11674_featured_image.jpg"},{"name":"Danica Patrick","rarity":"epic","id":"danica-patrick","subtitle":"Driver","details":"Patrick led laps at the 2005 Indianapolis 500 as a rookie, won at Motegi in 2008, and finished third at Indy in 2009, a record for a woman.","image":"assets/sets/compress/indy__danica-patrick.webp"},{"name":"Danny Sullivan","rarity":"epic","id":"danny-sullivan","subtitle":"Driver","details":"Sullivan spun in front of Mario Andretti, recovered, and won the 1985 Indianapolis 500 in the famous spin and win, then took the 1988 CART title.","image":"https://imsdotcom.azureedge.net/-/media/5C82C1EBA82D424FB6E686119F165894.ashx?vs=1&d=20180518T014323Z"},{"name":"Eddie Cheever","rarity":"epic","id":"eddie-cheever","subtitle":"Driver","details":"After more than a decade in Formula 1, Cheever won the 1998 Indianapolis 500 as a driver-owner with his own Team Cheever entry.","image":"https://nbcsports.brightspotcdn.com/dims4/default/6bc7919/2147483647/strip/true/crop/394x594+0+0/resize/394x594!/quality/90/?url=https%3A%2F%2Fnbc-sports-production-nbc-sports.s3.us-east-1.amazonaws.com%2Fbrightspot%2F50%2F2e%2Ffd9c6932e1ea93797b0cfe84ac18%2F316109.jpg"},{"name":"Felix Rosenqvist","rarity":"epic","id":"felix-rosenqvist","subtitle":"Driver","details":"Rosenqvist won the 2026 Indianapolis 500 for Meyer Shank Racing, edging David Malukas in the closest 1-2 finish in the race's history.","image":"https://images2.minutemediacdn.com/image/upload/c_crop,x_0,y_117,w_4138,h_2327/c_fill,w_1440,ar_1440:810,f_auto,q_auto,g_auto/images/ImagnImages/production/243/01kstwzpe7ffmrz30g7x.jpg"},{"name":"Fernando Alonso","rarity":"epic","id":"fernando-alonso","subtitle":"Driver","details":"Alonso's 2017 Indianapolis 500 run led 27 laps and earned Rookie of the Year; his failure to qualify in 2019 was an equally large headline.","image":"https://images.ctfassets.net/gy95mqeyjg28/6aQrMExkrQOL4TZB5zFzfw/3da7a055f80f09c7aab02ee76a882b40/lrWKINDY20171552_ZsC5Zx2_r6Eow00.JPG?w=3840&q=75&fm=webp&fit=fill"},{"name":"Gil de Ferran","rarity":"epic","id":"gil-de-ferran","subtitle":"Driver","details":"De Ferran won back-to-back CART championships in 2000 and 2001 for Penske, then added the 2003 Indianapolis 500 in his final season.","image":"https://d2i8ejbvsgsqtt.cloudfront.net/gallery/indycar/indy/2003/20030526-dhelrigel/med/DF5S3156.jpg"},{"name":"Graham Hill","rarity":"epic","id":"graham-hill","subtitle":"Driver","details":"Hill won the 1966 Indianapolis 500 as a rookie and remains the only driver to win Indy, the Le Mans 24 Hours and the Monaco Grand Prix.","image":"https://www.footmanjames.co.uk/media/kadhnm4h/graham-hill-driving-f1-lola-t90-at-1966-indy-500.jpg?rxy=0,0.5&width=440&height=293&v=1dcb3b8c1178250"},{"name":"Greg Moore","rarity":"epic","id":"greg-moore","subtitle":"Driver","details":"Moore won five CART races by the age of 24 and was a defining star of the late 1990s before he was killed in a crash at Fontana in 1999.","image":"https://images.fineartamerica.com/images/artworkimages/medium/1/moment-of-silence-james-smith.jpg"},{"name":"Jacques Villeneuve","rarity":"epic","id":"jacques-villeneuve","subtitle":"Driver","details":"Villeneuve recovered from a two-lap penalty to win the 1995 Indianapolis 500, then won the 1995 CART championship before leaving for Formula 1.","image":"https://d3cm515ijfiu6w.cloudfront.net/wp-content/uploads/2025/10/13203610/Jacques-Villeneuve-Formula-1-Indy-500-F1-PlanetF1-712x400.jpg"},{"name":"Jim Rathmann","rarity":"epic","id":"jim-rathmann","subtitle":"Driver","details":"Rathmann won the 1960 Indianapolis 500 after swapping the lead with Rodger Ward 29 times, in one of the most celebrated duels in race history.","image":"https://www.supercars.net/blog/wp-content/uploads/2011/11/Jim-Rathmann-1960-Indy-500-1-770x644.jpg"},{"name":"Jimmy Bryan","rarity":"epic","id":"jimmy-bryan","subtitle":"Driver","details":"Bryan won the 1958 Indianapolis 500 and three national championships, in 1954, 1956 and 1957, racing front-engined roadsters and dirt cars.","image":"https://d2i8ejbvsgsqtt.cloudfront.net/gallery/indycar/indy/1955/19550101-nphotographer/med/imsc4255.jpg"},{"name":"Jimmy Vasser","rarity":"epic","id":"jimmy-vasser","subtitle":"Driver","details":"Vasser won the 1996 CART championship and ten races with Ganassi, then became a winning IndyCar team co-owner with KV Racing.","image":"https://www.indycar.com/-/media/IndyCar/News/Other/2016/03/03-02-Vasser-Wins-At-Homestead.jpg"},{"name":"Kenny Bräck","rarity":"epic","id":"kenny-br-ck","subtitle":"Driver","details":"Brack won the 1998 IRL championship and followed it with the 1999 Indianapolis 500, driving for A.J. Foyt's own team.","image":"https://images-cdn.bridgemanimages.com/api/1.0/image/600wm.REU.07293480.7055475/8436091.jpg?old-wm"},{"name":"Marcus Ericsson","rarity":"epic","id":"marcus-ericsson","subtitle":"Driver","details":"Ericsson, a Formula 1 veteran, won the 2022 Indianapolis 500 for Ganassi by holding off Pato O'Ward after a late red flag restart.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/bc/Marcus_Ericsson_%282021%29.jpg/960px-Marcus_Ericsson_%282021%29.jpg"},{"name":"Mark Donohue","rarity":"epic","id":"mark-donohue","subtitle":"Driver","details":"Donohue won the 1972 Indianapolis 500, the first of Team Penske's twenty 500 wins, and set qualifying records in the McLaren M16.","image":"https://cf.nascar.com/nascar-galleries/gallery-images/2016/02/02/big_thumbnail/1972-McLaren-M16B-driven-by-Mark-Donahue.jpg"},{"name":"Nigel Mansell","rarity":"epic","id":"nigel-mansell","subtitle":"Driver","details":"Mansell arrived in 1993 as Formula 1 world champion and won the CART title as a rookie, finishing third in his only Indianapolis 500 that year.","image":"https://motorsportmagazine.b-cdn.net/wp-content/uploads/2022/08/1993-Newman-Haas-Lola-IndyCar-of-Nigel-mansell-800x450.jpg.webp"},{"name":"Parnelli Jones","rarity":"epic","id":"parnelli-jones","subtitle":"Driver","details":"Jones became the first driver to qualify at Indianapolis over 150 mph in 1962, then won the 1963 race in the famous Calhoun roadster.","image":"https://www.supercars.net/blog/wp-content/uploads/2013/01/Parnelli-Jones-Indy-1963-770x604.jpg"},{"name":"Pato O'Ward","rarity":"epic","id":"pato-o-ward","subtitle":"Driver","details":"O'Ward collected multiple IndyCar wins for Arrow McLaren and finished second at the Indianapolis 500 in both 2022 and 2024.","image":"https://images2.minutemediacdn.com/image/upload/c_crop,w_5497,h_3092,x_0,y_0/c_fill,w_2880,ar_16:9,f_auto,q_auto,g_auto/images/voltaxMediaLibrary/mmsport/f1briefings/01kkp6w96z8qtw2b46x7.jpg"},{"name":"Paul Tracy","rarity":"epic","id":"paul-tracy","subtitle":"Driver","details":"Tracy won the 2003 Champ Car championship and 31 top-level races, and finished second in the disputed finish of the 2002 Indianapolis 500.","image":"https://www.crash.net/sites/default/files/hires/39121.jpg?width=1600&aspect_ratio=16:9"},{"name":"Rex Mays","rarity":"epic","id":"rex-mays","subtitle":"Driver","details":"Mays took four Indianapolis 500 poles and two AAA championships in the 1930s and 1940s but never won the 500, and was killed at Del Mar in 1949.","image":"https://d2i8ejbvsgsqtt.cloudfront.net/gallery/indycar/indy/1948/19480101-nphotographer/med/imsc4111.jpg"},{"name":"Ryan Hunter-Reay","rarity":"epic","id":"ryan-hunter-reay","subtitle":"Driver","details":"Hunter-Reay won the 2012 IndyCar championship, then the 2014 Indianapolis 500 after a late duel with Helio Castroneves for Andretti.","image":"https://nbcsports.brightspotcdn.com/dims4/default/f11b7e9/2147483647/strip/true/crop/1024x576+0+54/resize/1440x810!/quality/90/?url=https%3A%2F%2Fnbc-sports-production-nbc-sports.s3.us-east-1.amazonaws.com%2Fbrightspot%2Fbf%2Fd4%2Ff1d6fbb3f897ad84bcc5ba4b1de7%2F539596628.jpg"},{"name":"Scott McLaughlin","rarity":"epic","id":"scott-mclaughlin","subtitle":"Driver","details":"After three Australian Supercars championships, McLaughlin won multiple IndyCar races for Penske and took pole for the 2024 Indianapolis 500.","image":"https://www.pennzoil.com/en_ca/performance/motorsports/scott-mclaughlin/_jcr_content/root/metadata.shellimg.jpeg/1742468299079/scot-mclaughlin-gallery-image-5.jpeg"},{"name":"Simon Pagenaud","rarity":"epic","id":"simon-pagenaud","subtitle":"Driver","details":"Pagenaud swept May 2019, winning the road course race, the pole and the Indianapolis 500 for Penske, after his 2016 IndyCar championship.","image":"https://www.rds.ca/resizer/v2/WK3QBXCLHW5ITL3AFRY7FQ3UMA.jpg?smart=true&auth=85a24937dce3d1a78d9985206f7ba4003f834b68aa49e061672d19fe605c385b&width=1600&height=899"},{"name":"Tom Sneva","rarity":"epic","id":"tom-sneva","subtitle":"Driver","details":"Sneva was the first driver to qualify over 200 mph at Indianapolis, in 1977, and won the 1983 race along with two USAC championships.","image":"assets/sets/compress/indy__tom-sneva.webp"},{"name":"Troy Ruttman","rarity":"epic","id":"troy-ruttman","subtitle":"Driver","details":"Ruttman won the 1952 Indianapolis 500 at 22 years old, and more than seven decades later he remains the youngest winner in race history.","image":"https://cdn.shopify.com/s/files/1/0339/0181/files/ruttman-lead.jpg?13809334704545330090"},{"name":"Honda Indy Toronto","rarity":"epic","id":"honda-indy-toronto","subtitle":"Track & Race","details":"Indy cars have raced around Exhibition Place in Toronto since 1986, on a tight street circuit beside Lake Ontario's shoreline.","image":"https://p1racenews.com/wp-content/uploads/2025/07/ontario-honda-dealers-indy-toronto-sunday-july-20-2025_large-image-without-watermark_m138121_0.jpg"},{"name":"Laguna Seca","rarity":"epic","id":"laguna-seca","subtitle":"Track & Race","details":"The Monterey County road course is famed for the Corkscrew, a blind downhill left-right dropping into Rainey Curve, and hosted many Indy car finales.","image":"https://cms.indycar.com/-/media/IndyCar/News/Standard/2022/07/07-07-Corkscrew.jpg"},{"name":"Michigan International Speedway","rarity":"epic","id":"michigan-international-speedway","subtitle":"Track & Race","details":"Michigan's two-mile superspeedway hosted 500-mile Indy car races under USAC, CART and the IRL, famous for wheel-to-wheel packs at speed.","image":"https://cdn-cs-images.racer.com/v3/assets/blte77f57883ea46be1/blt27c000f45212cd81/67dede41d43d1a2fc3c4e904/thumbnail_DRB_5356.jpg"},{"name":"Ontario Motor Speedway","rarity":"epic","id":"ontario-motor-speedway","subtitle":"Track & Race","details":"Built as a California replica of Indianapolis, Ontario hosted the California 500 from 1970 to 1980 before the speedway was demolished.","image":"https://cdn-cs-images.racer.com/v3/assets/blte77f57883ea46be1/blt2823d30bd1475670/67ea6647c475eec35e265ed2/ontario_front_row_1970-2.jpeg"},{"name":"Phoenix Raceway","rarity":"epic","id":"phoenix-raceway","subtitle":"Track & Race","details":"The one-mile desert oval outside Phoenix first hosted USAC Indy cars in 1964 and remained an open-wheel fixture into the modern IndyCar era.","image":"https://motorsportstribune.com/wp-content/uploads/2026/03/D260307IPR24308LDT.jpg"},{"name":"Road America","rarity":"epic","id":"road-america","subtitle":"Track & Race","details":"Road America's four-mile natural-terrain course at Elkhart Lake, Wisconsin has hosted Indy cars since 1982 among the Kettle Moraine hills.","image":"assets/sets/compress/indy__road-america.webp"},{"name":"Texas Motor Speedway","rarity":"epic","id":"texas-motor-speedway","subtitle":"Track & Race","details":"The high-banked 1.5-mile Fort Worth oval was an IndyCar fixture from 1997 to 2024, known for pack racing run at night under the lights.","image":"https://www.sportsbusinessjournal.com/resizer/v2/UJYEFZDT6BLF3ILZM2PWSBPQWA.jpg?auth=85e73bd1a79476f04ea24325281f2874fe678fa9c306fc17a33822f713f1c771&width=1440&height=959"},{"name":"Back Home Again in Indiana","rarity":"epic","id":"back-home-again-in-indiana","subtitle":"Moment","details":"Sung before the Indianapolis 500 since 1946, the song became inseparable from Jim Nabors, who performed it in most years from 1972 to 2014.","image":"https://d2i8ejbvsgsqtt.cloudfront.net/gallery/indycar/indy/1972/19720101-nphotographer/med/1972_Jim_Nabors.jpg"},{"name":"Danica Patrick Wins at Motegi","rarity":"epic","id":"danica-patrick-wins-at-motegi","subtitle":"Moment","details":"Patrick's 2008 victory at Twin Ring Motegi made her the first woman to win an IndyCar race, coming in her fourth season with Andretti Green.","image":"https://nbcsports.brightspotcdn.com/dims4/default/d4ee07d/2147483647/strip/true/crop/2148x1208+0+56/resize/1440x810!/quality/90/?url=https%3A%2F%2Fnbc-sports-production-nbc-sports.s3.us-east-1.amazonaws.com%2Fbrightspot%2Fae%2F5d%2Fc87e82d4391a842ade134f9d437d%2F80785273-e1451513424638.jpg"},{"name":"Double Duty","rarity":"epic","id":"double-duty","subtitle":"Moment","details":"Double Duty means racing the Indianapolis 500 and NASCAR's Coca-Cola 600 in one day; Tony Stewart completed all 1,100 miles of both in 2001.","image":"https://i.ebayimg.com/images/g/VdAAAOSwAQBarEjf/s-l960.webp"},{"name":"Janet Guthrie Breaks Through","rarity":"epic","id":"janet-guthrie-breaks-through","subtitle":"Moment","details":"In 1977 Guthrie became the first woman to qualify for and start the Indianapolis 500, finishing the race and returning to finish ninth in 1978.","image":"https://www.supercars.net/blog/wp-content/uploads/2012/05/28-IND177Indy-c55c.jpg"},{"name":"Scott Dixon's Laps-Led Record","rarity":"epic","id":"scott-dixon-s-laps-led-record","subtitle":"Moment","details":"Dixon led 665 laps across his Indianapolis 500 starts, more than any driver in the history of a race first run back in 1911.","image":"https://www.indycar.com/-/media/IndyCar/VideoImg/2018/05/05-11-Dixon-On-Course-IGP.jpg?vs=1&d=20180511T221928Z"},{"name":"The Greatest Spectacle in Racing","rarity":"epic","id":"the-greatest-spectacle-in-racing","subtitle":"Moment","details":"The slogan grew out of Speedway radio broadcasts in the 1950s and became the Indianapolis 500's worldwide identity and signature call.","image":"https://cdn-cs-images.racer.com/v3/assets/blte77f57883ea46be1/blt9bbad4f59193ca50/67eba797f68954392bbf53e3/indy-500-start-2.jpg"},{"name":"Victory Lane Milk","rarity":"epic","id":"victory-lane-milk","subtitle":"Moment","details":"Louis Meyer drank buttermilk after winning in 1936, and from 1956 the dairy industry made a bottle of milk the winner's permanent tradition.","image":"https://static0.carbuzzimages.com/wordpress/wp-content/uploads/gallery-images/original/1140000/500/1140558.jpg?q=50&fit=contain&w=1500&h=1000&dpr=1.5"},{"name":"Yard of Bricks","rarity":"epic","id":"yard-of-bricks","subtitle":"Moment","details":"A three-foot strip of bricks at the start-finish line is all left exposed of the 3.2 million bricks laid over the Speedway surface in 1909.","image":"assets/sets/compress/indy__yard-of-bricks.webp"},{"name":"Chaparral 2K","rarity":"epic","id":"chaparral-2k","subtitle":"Car & Era","details":"John Barnard's ground-effects Chaparral 2K carried Johnny Rutherford to the 1980 Indianapolis 500 win and reshaped Indy car aerodynamics.","image":"https://motorsportmagazine.b-cdn.net/wp-content/uploads/2014/07/Johnny-Rutherford-demonstrating-the-Chaparral-2K-at-Goodwood-Festival-of-Speed-2018.jpg.webp"},{"name":"Dallara DW12","rarity":"epic","id":"dallara-dw12","subtitle":"Car & Era","details":"The DW12 chassis, named in honour of Dan Wheldon, its test driver, became IndyCar's spec chassis in 2012 and defined a long era of parity.","image":"https://cdn-cms.f-static.com/uploads/213536/2000_597c4a54a8f67.jpg"},{"name":"Foyt Coyote","rarity":"epic","id":"foyt-coyote","subtitle":"Car & Era","details":"A.J. Foyt designed his own Coyote chassis and drove one to his fourth Indianapolis 500 victory in 1977, a win built at home in Houston.","image":"https://cdn-cs-images.racer.com/v3/assets/blte77f57883ea46be1/blt89fb9bb4679f9d58/67e05d4473b574a8b1ff24cd/1977_Foyt_action.jpg"},{"name":"McLaren M16","rarity":"epic","id":"mclaren-m16","subtitle":"Car & Era","details":"The McLaren M16 won the Indianapolis 500 in 1972, 1974 and 1976, making it the defining Indy car design of the sport's turbocharged seventies.","image":"assets/sets/compress/indy__mclaren-m16.webp"},{"name":"Watson Roadster","rarity":"epic","id":"watson-roadster","subtitle":"Car & Era","details":"A.J. Watson's front-engined roadsters won six Indianapolis 500s between 1956 and 1964, the peak of the roadster era before rear engines arrived.","image":"https://i.pinimg.com/originals/46/ad/8c/46ad8c16d1de782ecb24236b37f4d271.jpg"},{"name":"A.J. Foyt Enterprises","rarity":"epic","id":"a-j-foyt-enterprises","subtitle":"Team","details":"Foyt's own team entered Indy cars for decades, and Kenny Brack won the 1999 Indianapolis 500 in its colours for the Houston legend.","image":"https://motorsportamerica.com/dsc_5428/"},{"name":"Andretti Global","rarity":"epic","id":"andretti-global","subtitle":"Team","details":"Michael Andretti's team won five Indianapolis 500s, with Dan Wheldon in 2005, Dario Franchitti in 2007 and Alexander Rossi in 2016 among them.","image":"https://static.the562.org/wp-content/uploads/2025/04/2025-04-13_LBGPIndyRace-031.jpg"},{"name":"Newman/Haas Racing","rarity":"epic","id":"newman-haas-racing","subtitle":"Team","details":"Paul Newman and Carl Haas's team won 107 races and eight championships with drivers like Mario Andretti, but never the Indianapolis 500.","image":"https://rickcarey.com/wp-content/uploads/2022/11/RM-Newman-Haas-102922_141_Lola-Chevrolet_1988_T8800_Indy-Car_HU18-1536x1025.jpg"},{"name":"Patrick Racing","rarity":"epic","id":"patrick-racing","subtitle":"Team","details":"Pat Patrick's team won the Indianapolis 500 three times, with Gordon Johncock in 1973 and 1982 and Emerson Fittipaldi in 1989.","image":"https://theclassicmachines.com/wp-content/uploads/2021/07/1989-indy-500-sideways-victory-01-1024-1.jpg"},{"name":"Rahal Letterman Lanigan Racing","rarity":"epic","id":"rahal-letterman-lanigan-racing","subtitle":"Team","details":"Bobby Rahal's team won the Indianapolis 500 with Buddy Rice in 2004 and Takuma Sato in 2020, the second with David Letterman as co-owner.","image":"https://rahal.com/wp-content/uploads/2024/08/056cb54b-27d4-ad33-698d-31cbd74d586e-960x720.jpg"},{"name":"Adrian Fernández","rarity":"rare","id":"adrian-fern-ndez","subtitle":"Driver","details":"Mexico's leading Indy car star of his era, Fernández won 11 top-level races across CART and the IRL and drew huge home crowds.","image":"https://upload.wikimedia.org/wikipedia/commons/4/4f/Adri%C3%A1n_Fern%C3%A1ndez.jpg"},{"name":"Bill Cummings","rarity":"rare","id":"bill-cummings","subtitle":"Driver","details":"'Wild Bill' Cummings won the 1934 Indianapolis 500 and added the AAA national championship in 1937.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/59/Indy500winningcar1934.JPG/500px-Indy500winningcar1934.JPG"},{"name":"Bill Holland","rarity":"rare","id":"bill-holland","subtitle":"Driver","details":"Holland won the 1949 Indianapolis 500 after finishing second in 1947 and 1948, the first of them in famously disputed fashion.","image":"https://upload.wikimedia.org/wikipedia/commons/8/86/Bill_Holland_and_Linda_Darnell_1949_Indianapolis_500_%28cropped%29.jpg"},{"name":"Billy Arnold","rarity":"rare","id":"billy-arnold","subtitle":"Driver","details":"Arnold dominated the 1930 Indianapolis 500, leading 198 of the 200 laps to win the race as a 24-year-old.","image":"https://cdm17257.contentdm.oclc.org/digital/api/iiif/2/p17257coll1:156050/full/800,/0/default.jpg"},{"name":"Bob Sweikert","rarity":"rare","id":"bob-sweikert","subtitle":"Driver","details":"Sweikert won the tragic 1955 Indianapolis 500, the race in which two-time winner Bill Vukovich was killed in a crash.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7b/Indy500winningcar1955.JPG/500px-Indy500winningcar1955.JPG"},{"name":"Bruno Junqueira","rarity":"rare","id":"bruno-junqueira","subtitle":"Driver","details":"Junqueira sat on pole for the 2002 Indianapolis 500 and finished runner-up in the Champ Car championship three straight years, 2002 to 2004.","image":"https://upload.wikimedia.org/wikipedia/commons/d/d2/Bruno_Junqueira_2009_Indy_500_Pole_Day.JPG"},{"name":"Colton Herta","rarity":"rare","id":"colton-herta","subtitle":"Driver","details":"Herta won at Austin in March 2019 aged 18 to become IndyCar's youngest race winner, and has added multiple wins with Andretti.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e2/Colton_Herta_at_the_Melbourne_Walk_during_the_2026_Australian_Grand_Prix_%28028A8365%29_cropped.jpg/500px-Colton_Herta_at_the_Melbourne_Walk_during_the_2026_Australian_Grand_Prix_%28028A8365%29_cropped.jpg"},{"name":"Eddie Sachs","rarity":"rare","id":"eddie-sachs","subtitle":"Driver","details":"The 'Clown Prince' won back-to-back Indy poles in 1960 and 1961, finished second in 1961, and died in the fiery 1964 crash.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fb/American_Red_Ball_Halibrand_Ford_front_view_Honda_Collection_Hall.jpg/500px-American_Red_Ball_Halibrand_Ford_front_view_Honda_Collection_Hall.jpg"},{"name":"Floyd Roberts","rarity":"rare","id":"floyd-roberts","subtitle":"Driver","details":"Roberts won the 1938 Indianapolis 500 from pole position, then lost his life in a crash at the Speedway the following year.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f0/Floyd_Roberts_1934.jpg/500px-Floyd_Roberts_1934.jpg"},{"name":"Frank Lockhart","rarity":"rare","id":"frank-lockhart","subtitle":"Driver","details":"Lockhart won the rain-shortened 1926 Indianapolis 500 as a rookie, then died in 1928 chasing a land-speed record at Daytona Beach.","image":"https://upload.wikimedia.org/wikipedia/commons/9/9e/Frank_Lockhart_Indianapolis_1927.jpg"},{"name":"Fred Frame","rarity":"rare","id":"fred-frame","subtitle":"Driver","details":"Frame charged from 27th on the grid to win the 1932 Indianapolis 500, one of the great comeback drives of the early era.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/19/Indy500winningcar1932.JPG/500px-Indy500winningcar1932.JPG"},{"name":"Gaston Chevrolet","rarity":"rare","id":"gaston-chevrolet","subtitle":"Driver","details":"Gaston Chevrolet won the 1920 Indianapolis 500 in a Monroe, then was killed in a race at Beverly Hills later that same year.","image":"https://upload.wikimedia.org/wikipedia/commons/1/1b/Gaston_Chevrolet.jpg"},{"name":"George Robson","rarity":"rare","id":"george-robson","subtitle":"Driver","details":"Robson won the 1946 Indianapolis 500, the first running of the race held after the Second World War.","image":"https://upload.wikimedia.org/wikipedia/commons/1/11/George_Robson_Indianapolis_1946.jpg"},{"name":"George Souders","rarity":"rare","id":"george-souders","subtitle":"Driver","details":"Souders won the 1927 Indianapolis 500 in a Duesenberg, taking victory in the very first 500 start of his career.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/59/George_Souders_1927.jpg/500px-George_Souders_1927.jpg"},{"name":"Graham Rahal","rarity":"rare","id":"graham-rahal","subtitle":"Driver","details":"Son of 1986 winner Bobby, Graham Rahal won his first IndyCar start at St. Petersburg in 2008 and is a six-time series race winner.","image":"https://upload.wikimedia.org/wikipedia/commons/d/d7/Graham_Rahal_at_2024_Chevrolet_Detroit_Grand_Prix.jpg"},{"name":"Greg Ray","rarity":"rare","id":"greg-ray","subtitle":"Driver","details":"Ray won the 1999 IRL championship with Team Menard and started the 2000 Indianapolis 500 from pole position.","image":"https://www.speedsport-magazine.com/sites/default/files/styles/meldung_vorschau/public/meldeliste/team-menard-dallara-ir0-oldsmobile-ray-34889.jpg.webp?itok=iJrj6m2z"},{"name":"Harry Hartz","rarity":"rare","id":"harry-hartz","subtitle":"Driver","details":"Hartz finished second at Indianapolis three times without winning, then built the car Billy Arnold drove to victory in 1930.","image":"https://upload.wikimedia.org/wikipedia/commons/e/e6/Harry_Hartz_-_Feb_1924_UW.jpg"},{"name":"Howdy Wilcox","rarity":"rare","id":"howdy-wilcox","subtitle":"Driver","details":"Wilcox won the 1919 Indianapolis 500 in a Peugeot, taking the lead late and holding it for the final 98 laps.","image":"https://upload.wikimedia.org/wikipedia/en/c/cd/Howard_Samuel_Wilcox_1919.jpg"},{"name":"Jimmy Murphy","rarity":"rare","id":"jimmy-murphy","subtitle":"Driver","details":"Murphy won the 1922 Indianapolis 500 from pole position and added two AAA championships before his death in a 1924 dirt race.","image":"https://upload.wikimedia.org/wikipedia/commons/c/c1/JimmyMurphy08281920.jpg"},{"name":"Johnnie Parsons","rarity":"rare","id":"johnnie-parsons","subtitle":"Driver","details":"Parsons won the rain-shortened 1950 Indianapolis 500; the Borg-Warner Trophy engraves his name as 'Johnny' instead of Johnnie.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a8/Johnnie_Parsons_USAC_circa_1957.jpg/500px-Johnnie_Parsons_USAC_circa_1957.jpg"},{"name":"Jules Goux","rarity":"rare","id":"jules-goux","subtitle":"Driver","details":"Goux won the 1913 Indianapolis 500, becoming the first European driver to win the great American race.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4f/Jules_Goux_at_the_1921_French_Grand_Prix_%282%29_%28cropped%29.jpg/500px-Jules_Goux_at_the_1921_French_Grand_Prix_%282%29_%28cropped%29.jpg"},{"name":"Kelly Petillo","rarity":"rare","id":"kelly-petillo","subtitle":"Driver","details":"Petillo won the 1935 Indianapolis 500, the first 500 victory powered by the legendary Offenhauser engine.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/60/Kelly_Petillo_1941.jpg/500px-Kelly_Petillo_1941.jpg"},{"name":"Kyle Kirkwood","rarity":"rare","id":"kyle-kirkwood","subtitle":"Driver","details":"Kirkwood's IndyCar wins for Andretti include Long Beach in 2023 and 2025, Nashville in 2023 and Detroit in 2025.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e8/Kyle_Kirkwood_Freedom_250_Grand_Prix_%28cropped%29.jpg/500px-Kyle_Kirkwood_Freedom_250_Grand_Prix_%28cropped%29.jpg"},{"name":"Kyle Larson","rarity":"rare","id":"kyle-larson","subtitle":"Driver","details":"Larson, a NASCAR Cup champion, was the 2024 Indy 500 Rookie of the Year and attempted the Indy-Charlotte Double in 2024 and 2025.","image":"https://www.jayski.com/wp-content/uploads/sites/31/2024/5/26/GettyImages-2154793629-625x340.jpg"},{"name":"Lee Wallard","rarity":"rare","id":"lee-wallard","subtitle":"Driver","details":"Wallard won the 1951 Indianapolis 500 in the lightweight Belanger Special, then was badly burned in a sprint-car crash weeks later.","image":"https://upload.wikimedia.org/wikipedia/commons/3/3a/Leewallard.jpg"},{"name":"Lloyd Ruby","rarity":"rare","id":"lloyd-ruby","subtitle":"Driver","details":"Ruby started 18 Indianapolis 500s from 1960, led the race in several runnings, and took a best finish of third without ever winning.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b3/Lloyd_Ruby_%282534355548%29.jpg/500px-Lloyd_Ruby_%282534355548%29.jpg"},{"name":"Louis Schneider","rarity":"rare","id":"louis-schneider","subtitle":"Driver","details":"Schneider won the 1931 Indianapolis 500 aboard the Bowes Seal Fast Special, the biggest result of his racing career.","image":"assets/sets/compress/indy__louis-schneider.webp"},{"name":"Pancho Carter","rarity":"rare","id":"pancho-carter","subtitle":"Driver","details":"Carter won the inaugural Michigan 500 in 1981 and put the new Buick V6 engine on pole at Indianapolis in 1985.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/32/Pancho_carter_at_indy500_in_2011_%28cropped%29.JPG/500px-Pancho_carter_at_indy500_in_2011_%28cropped%29.JPG"},{"name":"Pat Flaherty","rarity":"rare","id":"pat-flaherty","subtitle":"Driver","details":"Flaherty won the 1956 Indianapolis 500 from pole position in a Watson roadster, in the roadster era's golden years.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b9/Indy500winningcar1956.JPG/500px-Indy500winningcar1956.JPG"},{"name":"Peter DePaolo","rarity":"rare","id":"peter-depaolo","subtitle":"Driver","details":"DePaolo won the 1925 Indianapolis 500, the first 500 run at an average speed above 100 miles per hour.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0b/PeteDePaoloJul1925Retouched.jpg/500px-PeteDePaoloJul1925Retouched.jpg"},{"name":"Ray Keech","rarity":"rare","id":"ray-keech","subtitle":"Driver","details":"Keech won the 1929 Indianapolis 500, then was killed in a crash at Altoona just weeks after his victory.","image":"https://upload.wikimedia.org/wikipedia/commons/8/89/Ray_Keech_n041941.jpg"},{"name":"René Thomas","rarity":"rare","id":"ren-thomas","subtitle":"Driver","details":"France's René Thomas won the 1914 Indianapolis 500 in a Delage, one of the last 500s run before the First World War.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7a/Ren%C3%A9_Thomas_at_1914_Indy_500.jpg/500px-Ren%C3%A9_Thomas_at_1914_Indy_500.jpg"},{"name":"Roberto Guerrero","rarity":"rare","id":"roberto-guerrero","subtitle":"Driver","details":"Guerrero finished second at Indy in 1984 and 1987, then took pole in 1992 with a record run before crashing on the pace lap.","image":"https://upload.wikimedia.org/wikipedia/commons/3/36/Roberto_Guerrero_2010_Indy_500_Practice_Day_7.JPG"},{"name":"Sam Hanks","rarity":"rare","id":"sam-hanks","subtitle":"Driver","details":"After a dozen near misses, Hanks won the 1957 Indianapolis 500 and announced his retirement in victory lane.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/54/Salih_Special_1957-58_Indy_500_Winner_-_Sam_Hanks_%26_Jimmy_Bryan.jpg/500px-Salih_Special_1957-58_Indy_500_Winner_-_Sam_Hanks_%26_Jimmy_Bryan.jpg"},{"name":"Scott Goodyear","rarity":"rare","id":"scott-goodyear","subtitle":"Driver","details":"Goodyear lost the 1992 500 by 0.043 seconds, then the closest finish ever, and a pace-car penalty cost him the 1995 lead.","image":"https://upload.wikimedia.org/wikipedia/commons/e/e8/Scott_Goodyear_2008_Indy_500_Second_Qual_Day.jpg"},{"name":"Scott Sharp","rarity":"rare","id":"scott-sharp","subtitle":"Driver","details":"Sharp was co-champion of the inaugural Indy Racing League season in 1996 and won races in both CART and the IRL.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/03/SharpIndy07.jpg/500px-SharpIndy07.jpg"},{"name":"Teo Fabi","rarity":"rare","id":"teo-fabi","subtitle":"Driver","details":"Fabi stunned Indianapolis in 1983 by taking pole for the 500 as a rookie, then won four CART races in that same season.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/36/Forsythe_Racing_1983_Indy_500_-_Teo_Fabi.jpg/500px-Forsythe_Racing_1983_Indy_500_-_Teo_Fabi.jpg"},{"name":"Tony Stewart","rarity":"rare","id":"tony-stewart","subtitle":"Driver","details":"Stewart won the 1997 IRL championship and started five Indy 500s, finishing a best of fifth in 1997, before his NASCAR fame.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ee/Tony_Stewart_2026.jpg/500px-Tony_Stewart_2026.jpg"},{"name":"Vitor Meira","rarity":"rare","id":"vitor-meira","subtitle":"Driver","details":"Meira finished second in the Indianapolis 500 twice, in 2005 and 2008, without ever winning an IndyCar series race.","image":"https://upload.wikimedia.org/wikipedia/commons/3/31/Vitor_Meira_2008_%282668145692%29_%28cropped%29.jpg"},{"name":"Walt Faulkner","rarity":"rare","id":"walt-faulkner","subtitle":"Driver","details":"Faulkner took pole for the 1950 Indianapolis 500 as a rookie with a record-breaking qualifying run.","image":"https://upload.wikimedia.org/wikipedia/commons/2/2b/Walt_Faulkner_circa_1948.jpg"},{"name":"Auto Club Speedway","rarity":"rare","id":"auto-club-speedway","subtitle":"Track & Race","details":"Fontana's two-mile superspeedway hosted CART and IndyCar 500-mile races, including some of the fastest races ever run.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/33/Carpenter2012mavtv500.JPG/500px-Carpenter2012mavtv500.JPG"},{"name":"Barber Motorsports Park","rarity":"rare","id":"barber-motorsports-park","subtitle":"Track & Race","details":"Barber's sculpted Alabama road course, famous for its museum and giant spider sculptures, has hosted the Grand Prix of Alabama since 2010.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/30/Barber_Motorsports_Park_Aerial_%2834804699780%29.jpg/500px-Barber_Motorsports_Park_Aerial_%2834804699780%29.jpg"},{"name":"Detroit Grand Prix","rarity":"rare","id":"detroit-grand-prix","subtitle":"Track & Race","details":"Indy cars have raced on Detroit streets since 1989, first downtown, then on Belle Isle, before returning downtown in 2023.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f0/2024_Chevrolet_Detroit_Grand_Prix_1.jpg/500px-2024_Chevrolet_Detroit_Grand_Prix_1.jpg"},{"name":"Grand Prix of Cleveland","rarity":"rare","id":"grand-prix-of-cleveland","subtitle":"Track & Race","details":"The CART and Champ Car race at Cleveland ran over Burke Lakefront Airport's wide, bumpy runways from 1982 to 2007.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/10/Mark_Smith_Formula_Super_Vee_Grand_Prix_of_Cleveland_1988.jpg/500px-Mark_Smith_Formula_Super_Vee_Grand_Prix_of_Cleveland_1988.jpg"},{"name":"Grand Prix of St. Petersburg","rarity":"rare","id":"grand-prix-of-st-petersburg","subtitle":"Track & Race","details":"St. Petersburg's waterfront street circuit in Florida has opened the IndyCar season in most years since 2005.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/70/2024_Grand_Prix_of_St_Petersburg_Grand_%2853582908302%29.jpg/500px-2024_Grand_Prix_of_St_Petersburg_Grand_%2853582908302%29.jpg"},{"name":"Iowa Speedway","rarity":"rare","id":"iowa-speedway","subtitle":"Track & Race","details":"Iowa's 7/8-mile Newton oval, designed with input from Rusty Wallace, brought IndyCar racing to the heartland in 2007.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8f/Scott_McLaughlin_and_%C3%81lex_Palou_at_the_2024_Hy-Vee_Homefront_250.jpg/500px-Scott_McLaughlin_and_%C3%81lex_Palou_at_the_2024_Hy-Vee_Homefront_250.jpg"},{"name":"Mid-Ohio Sports Car Course","rarity":"rare","id":"mid-ohio-sports-car-course","subtitle":"Track & Race","details":"Mid-Ohio's rolling Lexington road course first hosted Indy cars in 1980 and is a fixture of the modern IndyCar summer.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d6/OWard_MidOhio_2024_FastSix.jpg/500px-OWard_MidOhio_2024_FastSix.jpg"},{"name":"Pocono 500","rarity":"rare","id":"pocono-500","subtitle":"Track & Race","details":"The Pocono 500 was a 500-mile Triple Crown fixture under USAC and CART from 1971 to 1989, then an IndyCar round from 2013 to 2019.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8e/Race_start_%2843278915285%29.jpg/500px-Race_start_%2843278915285%29.jpg"},{"name":"Portland International Raceway","rarity":"rare","id":"portland-international-raceway","subtitle":"Track & Race","details":"Portland's flat Oregon road course has hosted CART, Champ Car and IndyCar racing since 1984, through several eras of the sport.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a1/Munoz_at_Portland.jpg/500px-Munoz_at_Portland.jpg"},{"name":"Surfers Paradise Street Circuit","rarity":"rare","id":"surfers-paradise-street-circuit","subtitle":"Track & Race","details":"Australia's Gold Coast street circuit hosted the Gold Coast Indy 300 from 1991 to 2008, Indy car racing's overseas showcase.","image":"https://upload.wikimedia.org/wikipedia/commons/7/71/Lexmark_indy_champ_car2_2006.jpg"},{"name":"Watkins Glen International","rarity":"rare","id":"watkins-glen-international","subtitle":"Track & Race","details":"Watkins Glen hosted USAC, CART and IndyCar races across five decades, the sport's New York road-course home.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/86/Watkins_Glen_Victory_Lane_July_4%2C_2010.JPG/500px-Watkins_Glen_Victory_Lane_July_4%2C_2010.JPG"},{"name":"World Wide Technology Raceway","rarity":"rare","id":"world-wide-technology-raceway","subtitle":"Track & Race","details":"The Gateway oval near St. Louis hosted Indy cars from 1997 and became an IndyCar staple again from 2017.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5d/IndyCar_Gateway.jpg/500px-IndyCar_Gateway.jpg"},{"name":"Al Unser's Show-Car Win","rarity":"rare","id":"al-unser-s-show-car-win","subtitle":"Moment","details":"Unser won the 1987 Indy 500 in a year-old March pulled from a hotel lobby display, becoming the race's oldest winner at 47.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ae/Indy500winningcar1987.JPG/500px-Indy500winningcar1987.JPG"},{"name":"Arie Luyendyk's Qualifying Records","rarity":"rare","id":"arie-luyendyk-s-qualifying-records","subtitle":"Moment","details":"Luyendyk's 1996 Indianapolis qualifying laps — 237.498 mph for one lap, 236.986 over four — remain the Speedway's track records.","image":"https://upload.wikimedia.org/wikipedia/commons/a/ab/Arie_Luyendyk_2010_Indy_500_Practice_Day_7.JPG"},{"name":"Bump Day","rarity":"rare","id":"bump-day","subtitle":"Moment","details":"Bump Day is the final day of Indy 500 qualifying, when faster late runs knock slower cars out of the 33-car starting field.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f6/Aiming_high_at_over_200_miles_per_hour_180519-F-RV963-1071.jpg/500px-Aiming_high_at_over_200_miles_per_hour_180519-F-RV963-1071.jpg"},{"name":"Closest Finish in 500 History","rarity":"rare","id":"closest-finish-in-500-history","subtitle":"Moment","details":"Felix Rosenqvist beat David Malukas by 0.023 seconds in the 2026 Indianapolis 500 — the narrowest winning margin in the race's history.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/eb/Rosenqvist_passes_Malukas_at_2026_Indy_500.jpg/500px-Rosenqvist_passes_Malukas_at_2026_Indy_500.jpg"},{"name":"Dan Wheldon's Last-Corner Win","rarity":"rare","id":"dan-wheldon-s-last-corner-win","subtitle":"Moment","details":"In 2011, rookie J.R. Hildebrand crashed in the final turn while leading, and Dan Wheldon swept past to win his second Indy 500.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/87/Dan_Wheldon_2011_Indy_500.jpg/500px-Dan_Wheldon_2011_Indy_500.jpg"},{"name":"Danny Sullivan's Spin and Win","rarity":"rare","id":"danny-sullivan-s-spin-and-win","subtitle":"Moment","details":"Sullivan spun a full 360 degrees passing Mario Andretti for the lead in the 1985 Indy 500, caught the car, and still won the race.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/18/DannySullivanAt2015indy500.JPG/500px-DannySullivanAt2015indy500.JPG"},{"name":"Gentlemen, Start Your Engines","rarity":"rare","id":"gentlemen-start-your-engines","subtitle":"Moment","details":"'Gentlemen, Start Your Engines' is the traditional Indianapolis start command, given for decades by Tony Hulman and his family.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e5/Mari_Hulman_George_-_2015_500_Festival_-_Stierch.jpg/500px-Mari_Hulman_George_-_2015_500_Festival_-_Stierch.jpg"},{"name":"Sam Hornish Jr.'s Last-Lap Pass","rarity":"rare","id":"sam-hornish-jr-s-last-lap-pass","subtitle":"Moment","details":"Hornish passed rookie Marco Andretti on the final straight in 2006 to win the Indy 500 by 0.0635 seconds.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e7/TSM350_-_2015_-_Sam_Hornish_Jr_-_Stierch.jpg/500px-TSM350_-_2015_-_Sam_Hornish_Jr_-_Stierch.jpg"},{"name":"The 33-Car Grid","rarity":"rare","id":"the-33-car-grid","subtitle":"Moment","details":"The Indy 500 starts 33 cars in 11 rows of three, a format rooted in an early formula for safe spacing on the 2.5-mile track.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9d/2020_Indy_500_start.jpg/500px-2020_Indy_500_start.jpg"},{"name":"The Astor Cup","rarity":"rare","id":"the-astor-cup","subtitle":"Moment","details":"The Astor Challenge Cup, commissioned for a 1915 race at Sheepshead Bay, has been IndyCar's championship trophy since 2011.","image":"https://upload.wikimedia.org/wikipedia/commons/e/ec/1916_Astor_Cup_auto_race.jpg"},{"name":"The Open-Wheel Split","rarity":"rare","id":"the-open-wheel-split","subtitle":"Moment","details":"American open-wheel racing split into CART and the Indy Racing League in 1996 and stayed divided until reunification in 2008.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4f/Indy500winningcar1996.JPG/500px-Indy500winningcar1996.JPG"},{"name":"Willy T. Ribbs","rarity":"rare","id":"willy-t-ribbs","subtitle":"Moment","details":"In 1991 Willy T. Ribbs became the first Black driver to start the Indianapolis 500, a barrier broken 80 years after the first race.","image":"https://upload.wikimedia.org/wikipedia/commons/3/32/Willy_T_ribbs_%2841737875944%29.jpg"},{"name":"Gurney Eagle","rarity":"rare","id":"gurney-eagle","subtitle":"Car & Era","details":"Dan Gurney's All American Racers Eagles were beautiful and fast — Bobby Unser won the 1968 Indianapolis 500 in one.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/81/Indianapolis_Motor_Speedway_Museum_May_2026_17_%28Bobby_Unser%27s_1968_Rislone_Special_Eagle%29.jpg/500px-Indianapolis_Motor_Speedway_Museum_May_2026_17_%28Bobby_Unser%27s_1968_Rislone_Special_Eagle%29.jpg"},{"name":"Kurtis Kraft Roadster","rarity":"rare","id":"kurtis-kraft-roadster","subtitle":"Car & Era","details":"Frank Kurtis's front-engine roadsters dominated Indianapolis in the early 1950s, winning six straight 500s from 1950 to 1955.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f6/Kurtis_Kraft_Roadster_%C2%AB_Fuel_Injection_Special_%C2%BB_Bill_Vukovich_WINNER_1953_%26_1954_INDY_500_INDIANAPOLIS_SPEEDWAY_MUSEUM_USA_%2855517547009%29.jpg/500px-Kurtis_Kraft_Roadster_%C2%AB_Fuel_Injection_Special_%C2%BB_Bill_Vukovich_WINNER_1953_%26_1954_INDY_500_INDIANAPOLIS_SPEEDWAY_MUSEUM_USA_%2855517547009%29.jpg"},{"name":"Lola T93/00","rarity":"rare","id":"lola-t93-00","subtitle":"Car & Era","details":"Nigel Mansell won the 1993 CART championship as a rookie in the Lola T93/00, straight after his Formula 1 world title.","image":"https://upload.wikimedia.org/wikipedia/commons/f/f1/Indy_Car_drivers_Mark_Smith_and_Nigel_Mansell.jpg"},{"name":"March 86C","rarity":"rare","id":"march-86c","subtitle":"Car & Era","details":"Adrian Newey's March 86C won back-to-back Indy 500s: Bobby Rahal in 1986 and Al Unser in a Penske-run car in 1987.","image":"https://upload.wikimedia.org/wikipedia/commons/3/30/Rahal1986Car.jpg"},{"name":"Offenhauser Engine","rarity":"rare","id":"offenhauser-engine","subtitle":"Car & Era","details":"The Offenhauser four-cylinder, the 'Offy', won a record 27 Indianapolis 500s between 1935 and 1976.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5c/Offenhauser_Midget_racing_engines_%281715803460%29.jpg/500px-Offenhauser_Midget_racing_engines_%281715803460%29.jpg"},{"name":"Reynard 95I","rarity":"rare","id":"reynard-95i","subtitle":"Car & Era","details":"Jacques Villeneuve won the 1995 Indianapolis 500 and the CART championship driving Reynard's 95I chassis.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/88/Reynard_95I_%28Andre_Ribeiro%29_front-right_Honda_Collection_Hall.jpg/500px-Reynard_95I_%28Andre_Ribeiro%29_front-right_Honda_Collection_Hall.jpg"},{"name":"STP Turbine Car 'Silent Sam'","rarity":"rare","id":"stp-turbine-car-silent-sam","subtitle":"Car & Era","details":"The 1967 STP turbine car 'Silent Sam' led 171 laps with Parnelli Jones before a small bearing failed near the finish.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/24/STP_Turbine.jpg/500px-STP_Turbine.jpg"},{"name":"Forsythe Racing","rarity":"rare","id":"forsythe-racing","subtitle":"Team","details":"Gerald Forsythe's team reached its peak in 2003, when Paul Tracy drove it to the Champ Car championship.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/89/Paul_Tracy_-_Forsythe_Racing_at_Druids_at_the_2003_Champcar_London_Trophy_race_%2850813832011%29.jpg/500px-Paul_Tracy_-_Forsythe_Racing_at_Druids_at_the_2003_Champcar_London_Trophy_race_%2850813832011%29.jpg"},{"name":"Galles Racing","rarity":"rare","id":"galles-racing","subtitle":"Team","details":"Rick Galles's team won the 1990 CART championship and the 1992 Indianapolis 500, both with Al Unser Jr. driving.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e0/Indy500winningcar1992.JPG/500px-Indy500winningcar1992.JPG"},{"name":"Meyer Shank Racing","rarity":"rare","id":"meyer-shank-racing","subtitle":"Team","details":"Little Meyer Shank Racing took its first Indy 500 win in 2021, when Hélio Castroneves scored his record-tying fourth.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/85/Helio_Castroneves_2021_Indy_500_Celebration.jpg/500px-Helio_Castroneves_2021_Indy_500_Celebration.jpg"},{"name":"Team Green","rarity":"rare","id":"team-green","subtitle":"Team","details":"Barry Green's Team Green won the 1995 Indianapolis 500 and CART championship double with Jacques Villeneuve.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d7/Jacques-villeneuve_CART-mid-ohio-1995_689.jpg/500px-Jacques-villeneuve_CART-mid-ohio-1995_689.jpg"},{"name":"Truesports","rarity":"rare","id":"truesports","subtitle":"Team","details":"Jim Trueman's Truesports won the 1986 Indianapolis 500 and consecutive CART titles in 1986 and 1987 with Bobby Rahal.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6d/1988TruesportsLolaJuddIndycar.jpg/500px-1988TruesportsLolaJuddIndycar.jpg"},{"name":"Airton Daré","rarity":"uncommon","id":"airton-dar","subtitle":"Driver","details":"Brazil's Daré scored his only IRL win at Kansas in 2002 for A.J. Foyt, and was the series' Rookie of the Year in 2000.","image":"https://d2i8ejbvsgsqtt.cloudfront.net/gallery/indycar/indy/2002/20020519-nphotographer/med/imsce5668.jpg"},{"name":"Alex Lloyd","rarity":"uncommon","id":"alex-lloyd","subtitle":"Driver","details":"Lloyd, the 2007 Indy Lights champion, finished fourth in the 2010 Indianapolis 500 and was named its Rookie of the Year.","image":"https://d2i8ejbvsgsqtt.cloudfront.net/gallery/indycar/indy/2008/20080517-cjones/med/04CJ0325-8089.jpg"},{"name":"Alex Tagliani","rarity":"uncommon","id":"alex-tagliani","subtitle":"Driver","details":"Tagliani won at Road America in 2004 and stunned the field by taking pole for the 2011 Indianapolis 500 with Sam Schmidt's team.","image":"https://d2i8ejbvsgsqtt.cloudfront.net/gallery/indy/2016/20160522-bkelley/med/41BK4259.jpg"},{"name":"André Ribeiro","rarity":"uncommon","id":"andr-ribeiro","subtitle":"Driver","details":"Ribeiro won three CART races for Tasman Motorsports in the mid-1990s, delivering Honda its first victories in the series.","image":"https://d2i8ejbvsgsqtt.cloudfront.net/gallery/indycar/indy/1995/19950101-nphotographer/med/imsc4543.jpg"},{"name":"Billy Boat","rarity":"uncommon","id":"billy-boat","subtitle":"Driver","details":"Boat won the 1998 IRL race at Texas for A.J. Foyt and started the 1999 Indianapolis 500 from pole position.","image":"https://d2i8ejbvsgsqtt.cloudfront.net/gallery/indycar/indy/2001/20010527-nphotographer/med/imscb0646.jpg"},{"name":"Bryan Herta","rarity":"uncommon","id":"bryan-herta","subtitle":"Driver","details":"Herta won back-to-back CART races at Laguna Seca in 1998 and 1999; in 1996 Zanardi's famous Corkscrew pass was made on him.","image":"https://hofcollection.com/cdn/shop/files/2006-bryan-herta.jpg?v=1712361130&width=533"},{"name":"Callum Ilott","rarity":"uncommon","id":"callum-ilott","subtitle":"Driver","details":"British driver Ilott has raced for Juncos Hollinger and Prema since 2021, with a best IndyCar finish of fifth at Laguna Seca in 2023.","image":"https://www.indycar.com/-/media/IndyCar/News/Standard/2024/03/03-27-Ilott.jpg"},{"name":"Carlos Muñoz","rarity":"uncommon","id":"carlos-mu-oz","subtitle":"Driver","details":"Muñoz finished second in the Indy 500 as a rookie in 2013 and again in 2016, and won a wet Detroit race in 2015.","image":"https://www.indycar.com/-/media/IndyCar/News/Standard/2017/12/12-19-Munoz-In-Pitstand-In-2016-AndrettiLogos.jpg?vs=1&d=20171219T150739Z"},{"name":"Charlie Kimball","rarity":"uncommon","id":"charlie-kimball","subtitle":"Driver","details":"Kimball won at Mid-Ohio in 2013 and spent a decade at the top level while racing with type 1 diabetes.","image":"https://www.indycar.com/-/media/IndyCar/News/Standard/2020/02/02-27-Kimball.jpg?vs=1&d=20200227T164651Z"},{"name":"Christian Rasmussen","rarity":"uncommon","id":"christian-rasmussen","subtitle":"Driver","details":"Denmark's Rasmussen broke through for his first IndyCar victory at the Milwaukee Mile in 2025 with Ed Carpenter Racing.","image":"https://ecrindy.com/wp-content/uploads/2026/06/CR-2027-980x735.jpg"},{"name":"Conor Daly","rarity":"uncommon","id":"conor-daly","subtitle":"Driver","details":"Daly finished second at Detroit in 2016 and took pole at Iowa in 2020, alongside a string of one-off Indy 500 appearances.","image":"https://www.indycar.com/-/media/IndyCar/News/Standard/2026/03/03-11-Daly-IC.jpg?vs=1&d=20260311T140936Z"},{"name":"Danny Ongais","rarity":"uncommon","id":"danny-ongais","subtitle":"Driver","details":"'Danny On-The-Gas' Ongais won USAC and CART races and survived one of the worst crashes in Indy 500 history in 1981.","image":"https://taziomagazine.com/wp-content/uploads/2022/03/Danny-Ongais_-1942-2022_LargeImageWithoutWatermark_m52460.jpg"},{"name":"Darren Manning","rarity":"uncommon","id":"darren-manning","subtitle":"Driver","details":"Britain's Manning was a CART and IndyCar regular from 2002 to 2009, driving for teams including Ganassi and A.J. Foyt.","image":"https://d2i8ejbvsgsqtt.cloudfront.net/gallery/indycar/nashville/2008/20080711-dgarrett/med/3DRG2258-5283.jpg"},{"name":"Davey Hamilton","rarity":"uncommon","id":"davey-hamilton","subtitle":"Driver","details":"Hamilton was an early IRL front-runner who fought back from severe leg injuries in a 2001 Texas crash to race the 500 again in 2007.","image":"https://www.speedsport-magazine.com/media/images/meldeliste/zoom1000/de-ferran-dragon-racing-dallara-ir-05-honda-hamilton-17185.jpg"},{"name":"David Malukas","rarity":"uncommon","id":"david-malukas","subtitle":"Driver","details":"Malukas stood on the Gateway podium in 2022 and 2023 and was classified second at the 2025 Indianapolis 500 for A.J. Foyt Racing.","image":"https://digbza2f4g9qo.cloudfront.net/-/media/IndyCar/Drivers/IndyCar-Series/Headshot/DavidMalukas.jpg?h=301&iar=0&w=375&vs=1&d=20240130T134506Z"},{"name":"Dick Simon","rarity":"uncommon","id":"dick-simon","subtitle":"Driver","details":"Simon made 17 Indianapolis 500 starts between 1970 and 1995, then fielded cars for many other drivers as an owner.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b6/DickSimonSVRA2016.jpg/500px-DickSimonSVRA2016.jpg"},{"name":"Ed Jones","rarity":"uncommon","id":"ed-jones","subtitle":"Driver","details":"Jones finished third at the 2017 Indy 500 and was its Rookie of the Year; he raced full-time from 2017 to 2019 and again in 2021.","image":"https://www.indycar.com/-/media/IndyCar/News/Standard/2021/01/01-27-DCRVS-Ed-Jones.jpg"},{"name":"Felipe Giaffone","rarity":"uncommon","id":"felipe-giaffone","subtitle":"Driver","details":"Giaffone won at Kentucky in 2002 and finished third in that year's Indianapolis 500, the peak of his IRL career.","image":"https://d2i8ejbvsgsqtt.cloudfront.net/gallery/indycar/phoenix/2006/20060125-rmcqueeney/med/1rmc2344.jpg"},{"name":"Gary Bettenhausen","rarity":"uncommon","id":"gary-bettenhausen","subtitle":"Driver","details":"Gary Bettenhausen made 21 Indy 500 starts and led most of the 1972 race before a late failure; his father Tony was a champion of the era.","image":"https://d2i8ejbvsgsqtt.cloudfront.net/gallery/indycar/indy/1975/19750101-nphotographer/med/imsc4887.jpg"},{"name":"Hideki Mutoh","rarity":"uncommon","id":"hideki-mutoh","subtitle":"Driver","details":"Japan's Mutoh was the 2008 IndyCar Rookie of the Year with Andretti Green Racing, with a best finish of second at Iowa.","image":"https://d2i8ejbvsgsqtt.cloudfront.net/gallery/indycar/richmond/2008/20080627-cjones/med/04CJ5944-7869.jpg"},{"name":"Jack Harvey","rarity":"uncommon","id":"jack-harvey","subtitle":"Driver","details":"Harvey took a podium third at the Indianapolis road-course race in 2019 and was a multi-season regular with Meyer Shank and Rahal.","image":"https://www.indianapolismotorspeedway.com/-/media/IMS/article-images/2025/09/24/15/16/09-24-Harvey-IMS.jpg?cw=480&h=270&crop=1"},{"name":"James Hinchcliffe","rarity":"uncommon","id":"james-hinchcliffe","subtitle":"Driver","details":"Hinchcliffe won six IndyCar races and the 2016 Indy 500 pole, a year after surviving a near-fatal practice crash at the same track.","image":"assets/sets/compress/indy__james-hinchcliffe.webp"},{"name":"Jaques Lazier","rarity":"uncommon","id":"jaques-lazier","subtitle":"Driver","details":"Jaques Lazier, younger brother of 1996 winner Buddy, scored his own IRL win at Chicagoland in 2001 for Team Menard.","image":"https://d2i8ejbvsgsqtt.cloudfront.net/gallery/indycar/kentucky/2009/20090731-rmcqueeney/med/1RMC4024-6347.jpg"},{"name":"Jeff Ward","rarity":"uncommon","id":"jeff-ward","subtitle":"Driver","details":"Motocross legend Ward crossed over to Indy cars, finishing second in the 1999 Indy 500 and winning at Texas in 2002.","image":"https://d2i8ejbvsgsqtt.cloudfront.net/gallery/indycar/indy/2005/20050522-rmcqueeney/med/LX5X2392.jpg"},{"name":"John Andretti","rarity":"uncommon","id":"john-andretti","subtitle":"Driver","details":"Won the 1991 CART race at Surfers Paradise, and added stock-car wins at Daytona and Martinsville plus a Rolex 24 victory.","image":"https://www.indianapolismotorspeedway.com/-/media/IMS/Photo-Galleries/2020/01/john-andretti-through-the-years-at-ims/2020/01/31/18/04/1994-JOHN-ANDRETTI-QUAL-CAR33.jpeg?h=1000&crop=1"},{"name":"Johnny Parsons Jr.","rarity":"uncommon","id":"johnny-parsons-jr","subtitle":"Driver","details":"Son of 1950 winner Johnnie Parsons, he was an Indy 500 regular in the 1980s and 1990s, with a best finish of fifth in 1985.","image":"https://d2i8ejbvsgsqtt.cloudfront.net/gallery/indycar/indy/1979/19790101-nphotographer/med/imsc5056.jpg"},{"name":"JR Hildebrand","rarity":"uncommon","id":"jr-hildebrand","subtitle":"Driver","details":"Leading the 2011 Indy 500 on the final lap, he hit the Turn 4 wall and still slid across the bricks second in a famous near-win.","image":"https://www.indycar.com/-/media/IndyCar/News/Standard/2019/04/04-22-JR-Hildebrand.jpg?vs=1&d=20190422T134842Z"},{"name":"Justin Wilson","rarity":"uncommon","id":"justin-wilson","subtitle":"Driver","details":"The tall British driver won in both Champ Car and IndyCar, highlighted by a popular victory at Texas in 2012 for Dale Coyne Racing.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/cc/Justin_Wilson_%282013%29.jpg/960px-Justin_Wilson_%282013%29.jpg"},{"name":"Kevin Cogan","rarity":"uncommon","id":"kevin-cogan","subtitle":"Driver","details":"Won the 1986 CART opener at Phoenix, then finished second to Bobby Rahal in that year's Indianapolis 500 at the Speedway.","image":"https://www.supercars.net/blog/wp-content/uploads/2023/11/imsc5603-1155x770.jpg"},{"name":"Kosuke Matsuura","rarity":"uncommon","id":"kosuke-matsuura","subtitle":"Driver","details":"The 2004 IndyCar Rookie of the Year with Super Aguri Fernandez Racing, he was a series regular through the late 2000s.","image":"https://d2i8ejbvsgsqtt.cloudfront.net/gallery/indycar/iowa/2007/20070623-ssnoddy/med/6SMS9045-8339.jpg"},{"name":"Kyffin Simpson","rarity":"uncommon","id":"kyffin-simpson","subtitle":"Driver","details":"A Chip Ganassi Racing regular from 2024, he charged from 13th to third at Toronto in 2025 for the first podium of his IndyCar career.","image":"https://www.the-race.com/content/images/size/w1000/2024/08/Kyffin-Simpson---Honda-Indy-200-at-Mid-Ohio---By_-Paul-Hurley_Large-Image-Without-Watermark_m111537.jpg"},{"name":"Lyn St. James","rarity":"uncommon","id":"lyn-st-james","subtitle":"Driver","details":"The 1992 Indy 500 Rookie of the Year, she started the race seven times between 1992 and 2000, a trailblazing run at the Speedway.","image":"https://d2i8ejbvsgsqtt.cloudfront.net/gallery/indycar/indy/1992/19920101-nphotographer/med/1992_Lynn_St_James_hs.jpg"},{"name":"Marco Andretti","rarity":"uncommon","id":"marco-andretti","subtitle":"Driver","details":"Third-generation Andretti who won at Sonoma in 2006 and Iowa in 2011, and stunned the field by taking the 2020 Indy 500 pole.","image":"https://www.indycar.com/-/media/IndyCar/News/Standard/2018/05/05-16-Andretti-On-Pitlane-IMS.jpg"},{"name":"Marcus Armstrong","rarity":"uncommon","id":"marcus-armstrong","subtitle":"Driver","details":"IndyCar's 2023 Rookie of the Year, the New Zealander scored his first series podium with third place at Detroit in 2024.","image":"https://cdn-cs-images.racer.com/v3/assets/blte77f57883ea46be1/bltf53235cf7d5d4274/67d41d884465d96d11456d65/Marcus-Armstrong-Sonsio-Grand-Prix-at-Road-America-By_-Travis-Hinkle_Large-Image-Without-Watermark_m84873.jpg?environment=live&width=1200&height=630&fit=crop"},{"name":"Mark Blundell","rarity":"uncommon","id":"mark-blundell","subtitle":"Driver","details":"The British ex-Formula 1 driver won three CART races in a breakout 1997 season with PacWest, including a Portland photo finish.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/99/Mark_Blundell_portrait_2011_%28cropped%29.jpg/500px-Mark_Blundell_portrait_2011_%28cropped%29.jpg"},{"name":"Mark Dismore","rarity":"uncommon","id":"mark-dismore","subtitle":"Driver","details":"Won the 1999 IRL race at Las Vegas for Kelley Racing and made seven Indianapolis 500 starts across a long top-level career.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/a/ab/MarkDismore2016.jpg/1280px-MarkDismore2016.jpg"},{"name":"Mauricio Gugelmin","rarity":"uncommon","id":"mauricio-gugelmin","subtitle":"Driver","details":"Won at Vancouver in 1997 and set a famous 240 mph closed-course qualifying lap at Fontana that same year for PacWest.","image":"assets/sets/compress/indy__mauricio-gugelmin.webp"},{"name":"Max Chilton","rarity":"uncommon","id":"max-chilton","subtitle":"Driver","details":"The former Formula 1 driver raced four IndyCar seasons for Ganassi and Carlin, and led 50 laps of the 2017 Indianapolis 500.","image":"https://www.indianapolismotorspeedway.com/-/media/IMS/article-images/2016/12/07/13/57/2016_VICS_Chilton2_1600x800.jpg?cw=480&h=270&crop=1"},{"name":"Max Papis","rarity":"uncommon","id":"max-papis","subtitle":"Driver","details":"Italy's 'Mad Max' won three CART races for Team Rahal from 1999 to 2001 and later served as an IndyCar race steward.","image":"assets/sets/compress/indy__max-papis.webp"},{"name":"Michel Jourdain Jr.","rarity":"uncommon","id":"michel-jourdain-jr","subtitle":"Driver","details":"A CART regular from 1996, the Mexican broke through with wins at Milwaukee and Montreal in 2003 driving for Team Rahal.","image":"https://cms.indycar.com/-/media/IndyCar/News/Standard/2021/07/07-27-Jourdain.jpg"},{"name":"Mike Conway","rarity":"uncommon","id":"mike-conway","subtitle":"Driver","details":"A street-course specialist, he won at Long Beach in 2011 and Detroit in 2013 during an IndyCar run from 2009 to 2014.","image":"https://www.fia.com/sites/default/files/styles/centerize_item/public/news/main_image/mike_conway_2016_pre_le_mans.jpg?itok=EhCmxY7o"},{"name":"Mike Mosley","rarity":"uncommon","id":"mike-mosley","subtitle":"Driver","details":"A three-time USAC winner, he started 15 Indianapolis 500s between 1967 and 1981 and finished third in the 1979 race.","image":"https://d2i8ejbvsgsqtt.cloudfront.net/gallery/indycar/indy/1973/19730101-nphotographer/med/imsc4821.jpg"},{"name":"Nolan Siegel","rarity":"uncommon","id":"nolan-siegel","subtitle":"Driver","details":"An Arrow McLaren full-timer from mid-2024, he won the LMP2 class at Le Mans that year, weeks before his 20th birthday.","image":"https://d2i8ejbvsgsqtt.cloudfront.net/gallery/indy/2025/20250517-jskibinski/med/_1JGS-2025-INDIANAPOLIS-500-254518-1.jpg"},{"name":"Oriol Servià","rarity":"uncommon","id":"oriol-servi","subtitle":"Driver","details":"The Spaniard won at Montreal in 2005 and finished runner-up in the Champ Car standings that year, across a two-decade career.","image":"https://www.indycar.com/-/media/IndyCar/News/Standard/2018/04/04-03-Servia-On-Pitlane-IMSTest2017.jpg"},{"name":"Patrick Carpentier","rarity":"uncommon","id":"patrick-carpentier","subtitle":"Driver","details":"One of Canada's top open-wheel regulars, he won five CART races for Player's Forsythe between 2001 and 2004.","image":"https://d2i8ejbvsgsqtt.cloudfront.net/gallery/indycar/homestead/2005/20050118-rmcqueeney/med/gu1m0726.jpg"},{"name":"Pippa Mann","rarity":"uncommon","id":"pippa-mann","subtitle":"Driver","details":"The British driver started seven Indianapolis 500s between 2011 and 2019, mostly in Dale Coyne Racing entries.","image":"https://www.indycar.com/-/media/IndyCar/News/Standard/2016/05/05-02-Mann-Enters-Indy500.jpg"},{"name":"Rinus VeeKay","rarity":"uncommon","id":"rinus-veekay","subtitle":"Driver","details":"Won the 2021 Indianapolis road course race with Ed Carpenter Racing and qualified on the Indy 500 front row three straight years.","image":"https://d2i8ejbvsgsqtt.cloudfront.net/gallery/portland/2024/20240824-jskibinski/med/_1JGS-2024-PORTLAND-446986-1.jpg"},{"name":"Robbie Buhl","rarity":"uncommon","id":"robbie-buhl","subtitle":"Driver","details":"A two-time IRL winner in the series' early years, he later co-owned Dreyer & Reinbold Racing while still driving its cars.","image":"https://d2i8ejbvsgsqtt.cloudfront.net/gallery/indycar/indy/2001/20010527-nphotographer/med/imscb0158.jpg"},{"name":"Roger Yasukawa","rarity":"uncommon","id":"roger-yasukawa","subtitle":"Driver","details":"The Japanese-American driver debuted with Super Aguri Fernandez in 2003 and remained an IndyCar regular through the 2000s.","image":"https://d2i8ejbvsgsqtt.cloudfront.net/gallery/indycar/motegi/2009/20090918-dgarrett/med/3DRG6148-1963.jpg"},{"name":"Ryan Briscoe","rarity":"uncommon","id":"ryan-briscoe","subtitle":"Driver","details":"The Australian won eight IndyCar races for Penske and Ganassi, and took pole for the 2012 Indianapolis 500, finishing fifth.","image":"https://www.indycar.com/-/media/IndyCar/News/Standard/2014/10/10-01-Briscoe-On-PitLane-Fontana-Std.jpg"},{"name":"Sam Schmidt","rarity":"uncommon","id":"sam-schmidt","subtitle":"Driver","details":"Won the 1999 IRL race at Las Vegas before a testing crash in 2000 left him paralysed; he became a leading team owner.","image":"assets/sets/compress/indy__sam-schmidt.webp"},{"name":"Santino Ferrucci","rarity":"uncommon","id":"santino-ferrucci","subtitle":"Driver","details":"An oval standout for A. J. Foyt Racing, he stacked up Indy 500 top-10 finishes year after year, peaking with third in 2023.","image":"https://indycar.com/-/media/IndyCar/Drivers/IndyCar-Series/Headshot/SantinoFerrucci.jpg?h=470&la=en&w=585"},{"name":"Sarah Fisher","rarity":"uncommon","id":"sarah-fisher","subtitle":"Driver","details":"She made nine Indianapolis 500 starts and scored an IRL podium in 2001, then became a team owner and the pace car driver.","image":"assets/sets/compress/indy__sarah-fisher.webp"},{"name":"Simona de Silvestro","rarity":"uncommon","id":"simona-de-silvestro","subtitle":"Driver","details":"The Swiss driver was the 2010 Indy 500 Rookie of the Year and finished second at Houston in 2013, her best IndyCar result.","image":"https://www.parettaasphotos.com/img-get/I0000ozH2lC5kktk/s/750/750/21bc-indy500-07161.jpg"},{"name":"Stefan Johansson","rarity":"uncommon","id":"stefan-johansson","subtitle":"Driver","details":"The Swedish ex-Formula 1 driver raced CART in the mid-1990s for Bettenhausen Motorsports, collecting several podiums.","image":"https://motorsportmagazine.b-cdn.net/wp-content/uploads/2024/04/GettyImages-884707252.jpg"},{"name":"Sting Ray Robb","rarity":"uncommon","id":"sting-ray-robb","subtitle":"Driver","details":"Idaho's aptly named regular since 2023, he drove for Dale Coyne, Foyt and Juncos Hollinger, with a top-10 at Gateway in 2024.","image":"https://indycar.com/-/media/IndyCar/Drivers/IndyCar-Series/Driver-List/StingRayRobb.jpg?h=301&iar=0&w=375"},{"name":"Tomas Scheckter","rarity":"uncommon","id":"tomas-scheckter","subtitle":"Driver","details":"Son of 1979 F1 champion Jody, he won at Michigan in 2002 and Texas in 2005, and led 85 laps of the 2002 Indy 500 as a rookie.","image":"https://d2i8ejbvsgsqtt.cloudfront.net/gallery/indycar/watkinsglen/2007/20070707-dgarrett/med/3DRG8373-7367.jpg"},{"name":"Tony Bettenhausen Jr.","rarity":"uncommon","id":"tony-bettenhausen-jr","subtitle":"Driver","details":"Son of two-time national champion Tony Bettenhausen, he was a regular Indy 500 starter who later ran his own CART team.","image":"https://www.picclickimg.com/P3gAAOSwV3pexXzc/Tony-Bettenhausen-Jr-1983-10-Provimi-Veal-At.webp"},{"name":"Tora Takagi","rarity":"uncommon","id":"tora-takagi","subtitle":"Driver","details":"The Japanese driver raced two CART seasons and two IRL seasons in the early 2000s, with a best finish of fourth.","image":"https://d2i8ejbvsgsqtt.cloudfront.net/gallery/indycar/michigan/2004/20040731-cjones/med/IMG_0709.jpg"},{"name":"Wally Dallenbach","rarity":"uncommon","id":"wally-dallenbach","subtitle":"Driver","details":"A five-time USAC winner in the 1960s and 1970s, he later became CART's long-serving chief steward, a fixture of race control.","image":"assets/sets/compress/indy__wally-dallenbach.webp"},{"name":"Autódromo Hermanos Rodríguez","rarity":"uncommon","id":"aut-dromo-hermanos-rodr-guez","subtitle":"Track & Race","details":"Mexico City's Formula 1 circuit hosted CART and Champ Car races in two separate eras, in the early 1980s and again in the 2000s.","image":"https://motorblog.com.mx/wp-content/uploads/2022/05/8b85d58d26b3033bd58a65b1ba4a91f6-1024x683.jpg"},{"name":"Chicago Motor Speedway","rarity":"uncommon","id":"chicago-motor-speedway","subtitle":"Track & Race","details":"A one-mile oval in Cicero, Illinois, built inside a horse racing park, it hosted CART races from 1999 through 2002.","image":"assets/sets/compress/indy__chicago-motor-speedway.webp"},{"name":"Chicagoland Speedway","rarity":"uncommon","id":"chicagoland-speedway","subtitle":"Track & Race","details":"Joliet's 1.5-mile tri-oval produced a string of blanket IndyCar finishes from 2001 to 2010, several decided by inches.","image":"https://upload.wikimedia.org/wikipedia/commons/d/d4/Chicagoland_Speedway_ow.jpg"},{"name":"Edmonton City Centre Airport","rarity":"uncommon","id":"edmonton-city-centre-airport","subtitle":"Track & Race","details":"Racing on the runways of Edmonton's city airport, this temporary circuit hosted Indy car racing from 2005 through 2012.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6f/Edmonton_Indy_2012_%287654641234%29.jpg/500px-Edmonton_Indy_2012_%287654641234%29.jpg"},{"name":"Fundidora Park","rarity":"uncommon","id":"fundidora-park","subtitle":"Track & Race","details":"Monterrey's circuit wound through a former steel foundry turned public park and hosted CART and Champ Car from 2001 to 2006.","image":"https://upload.wikimedia.org/wikipedia/commons/2/20/Fundidora_mty.jpg"},{"name":"Grand Prix of Baltimore","rarity":"uncommon","id":"grand-prix-of-baltimore","subtitle":"Track & Race","details":"Baltimore's Inner Harbor street circuit hosted three IndyCar races from 2011 to 2013, running past the harbor and Camden Yards.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/80/Will_Power%27s_car_-_2011_Baltimore_Grand_Prix.jpg/500px-Will_Power%27s_car_-_2011_Baltimore_Grand_Prix.jpg"},{"name":"Grand Prix of Houston","rarity":"uncommon","id":"grand-prix-of-houston","subtitle":"Track & Race","details":"Houston hosted street racing in two homes, downtown and Reliant Park, under CART, Champ Car and IndyCar between 1998 and 2014.","image":"https://upload.wikimedia.org/wikipedia/commons/0/0b/2007GPofHouston1.jpg"},{"name":"Homestead-Miami Speedway","rarity":"uncommon","id":"homestead-miami-speedway","subtitle":"Track & Race","details":"This Florida oval opened CART's seasons from 1996 and served as IndyCar's championship finale venue through the 2010 season.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/98/Homestead_Miami_Speedway_Panaramic_%2822692235444%29.jpg/500px-Homestead_Miami_Speedway_Panaramic_%2822692235444%29.jpg"},{"name":"Kansas Speedway","rarity":"uncommon","id":"kansas-speedway","subtitle":"Track & Race","details":"A 1.5-mile tri-oval in Kansas City that hosted IndyCar racing every year from its opening in 2001 through the 2010 season.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c4/Kansas_Speedway_Aerial.jpg/500px-Kansas_Speedway_Aerial.jpg"},{"name":"Kentucky Speedway","rarity":"uncommon","id":"kentucky-speedway","subtitle":"Track & Race","details":"Sparta's 1.5-mile tri-oval hosted IRL and IndyCar racing from 2000 to 2011, known for fast packs and close oval finishes.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b7/Kentucky_Speedway_%285920286681%29.jpg/500px-Kentucky_Speedway_%285920286681%29.jpg"},{"name":"Las Vegas Motor Speedway","rarity":"uncommon","id":"las-vegas-motor-speedway","subtitle":"Track & Race","details":"The 1.5-mile Las Vegas oval hosted IRL and Champ Car races and the 2011 IndyCar finale, the race where Dan Wheldon was lost.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0f/J.R._Hildebrand_IndyCar_Finale_Las_Vegas_2011.jpg/500px-J.R._Hildebrand_IndyCar_Finale_Las_Vegas_2011.jpg"},{"name":"Molson Indy Vancouver","rarity":"uncommon","id":"molson-indy-vancouver","subtitle":"Track & Race","details":"Vancouver's Concord Pacific street circuit hosted CART and Champ Car's Molson Indy from 1990 through the 2004 season.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/12/Mark_Smith_1993_Molson_Indy_Vancouver_GP.jpg/500px-Mark_Smith_1993_Molson_Indy_Vancouver_GP.jpg"},{"name":"Nashville Superspeedway","rarity":"uncommon","id":"nashville-superspeedway","subtitle":"Track & Race","details":"The concrete 1.33-mile Tennessee oval hosted IndyCar from 2001 to 2008, then returned as the season finale venue in 2024.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/df/EM_NASHVILLE_SUPERSPEEDWAY_%283283565118%29.jpg/500px-EM_NASHVILLE_SUPERSPEEDWAY_%283283565118%29.jpg"},{"name":"Nazareth Speedway","rarity":"uncommon","id":"nazareth-speedway","subtitle":"Track & Race","details":"The Andretti family's home track in Pennsylvania, this quirky mile oval hosted CART and IRL racing until it closed in 2004.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/84/NazerethSpeedway.jpg/500px-NazerethSpeedway.jpg"},{"name":"New Hampshire Motor Speedway","rarity":"uncommon","id":"new-hampshire-motor-speedway","subtitle":"Track & Race","details":"Loudon's flat one-mile oval hosted CART, IRL and IndyCar races in spells between 1992 and 2011, rewarding patient drivers.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fb/New_Hampshire_International_Speedway_%282007%29.jpg/500px-New_Hampshire_International_Speedway_%282007%29.jpg"},{"name":"Riverside International Raceway","rarity":"uncommon","id":"riverside-international-raceway","subtitle":"Track & Race","details":"California's classic road course, where Dan Gurney won the 1967 USAC Rex Mays 300, was lost to development in the late 1980s.","image":"https://upload.wikimedia.org/wikipedia/commons/2/2a/Dave_MacDonald_driving_his_Corvette_Special_at_Riverside_1962.jpg"},{"name":"Sonoma Raceway","rarity":"uncommon","id":"sonoma-raceway","subtitle":"Track & Race","details":"The hillside Northern California road course, long known as Sears Point and Infineon, hosted IndyCar from 2005 through 2018.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7d/Will_Power_Sonoma_2010.jpg/500px-Will_Power_Sonoma_2010.jpg"},{"name":"São Paulo Indy 300","rarity":"uncommon","id":"s-o-paulo-indy-300","subtitle":"Track & Race","details":"Staged around São Paulo's Anhembi Sambadrome, this street race opened the IndyCar season four straight years, 2010 to 2013.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6f/Justin_Wilson_%E2%80%93_2010_IZOD_IndyCar_Series_%E2%80%93_S%C3%A3o_Paulo_Indy_300_%E2%80%93_%281%29.jpg/500px-Justin_Wilson_%E2%80%93_2010_IZOD_IndyCar_Series_%E2%80%93_S%C3%A3o_Paulo_Indy_300_%E2%80%93_%281%29.jpg"},{"name":"Trenton Speedway","rarity":"uncommon","id":"trenton-speedway","subtitle":"Track & Race","details":"New Jersey's kidney-shaped oval was a USAC and CART fixture for decades before its final Indy car race in 1979.","image":"https://www.autoracing1.com/wp-content/uploads/historic/big/mario4-74trenton1.jpg"},{"name":"Twin Ring Motegi","rarity":"uncommon","id":"twin-ring-motegi","subtitle":"Track & Race","details":"Honda's Japanese superspeedway hosted CART and IndyCar from 1998 to 2011, the series' long-running trip across the Pacific.","image":"https://upload.wikimedia.org/wikipedia/commons/6/6d/First_lap_of_the_2008_Indy_Japan_300.jpg"},{"name":"Alexander Rossi's Fuel-Mileage Stunner","rarity":"uncommon","id":"alexander-rossi-s-fuel-mileage-stunner","subtitle":"Moment","details":"Rookie Alexander Rossi stretched one tank of fuel to a coasting, improbable win in the 100th Indianapolis 500 in 2016.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/66/Indy_500_winner_Alexander_Rossi_waving_to_crowd%2C_Indianapolis_Motor_Speedway%2C_May_2016.jpg/500px-Indy_500_winner_Alexander_Rossi_waving_to_crowd%2C_Indianapolis_Motor_Speedway%2C_May_2016.jpg"},{"name":"Baby Borg","rarity":"uncommon","id":"baby-borg","subtitle":"Moment","details":"Since 1988, every Indy 500 winner has received a miniature sterling replica of the Borg-Warner Trophy, the Baby Borg, to keep.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/17/Small_Borg-Warner_Trophies_-_Indianapolis_Motor_Speedway_Museum_-_Indianapolis%2C_Indiana_-_Stierch.jpg/500px-Small_Borg-Warner_Trophies_-_Indianapolis_Motor_Speedway_Museum_-_Indianapolis%2C_Indiana_-_Stierch.jpg"},{"name":"Carb Day","rarity":"uncommon","id":"carb-day","subtitle":"Moment","details":"The final practice day before the 500 keeps a name from the carburetor era, and shares the day with the Pit Stop Challenge.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7d/2017_Indianapolis_500_Carb_Day_Pit_Stop_Challenge_-_07.jpg/500px-2017_Indianapolis_500_Carb_Day_Pit_Stop_Challenge_-_07.jpg"},{"name":"Fast Friday","rarity":"uncommon","id":"fast-friday","subtitle":"Moment","details":"On the Friday before qualifying weekend, boost rises to qualifying trim and the fastest laps of the Month of May appear.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bf/Will_Power_2010_Indy_500_Practice_Day_7.JPG/500px-Will_Power_2010_Indy_500_Practice_Day_7.JPG"},{"name":"Gasoline Alley","rarity":"uncommon","id":"gasoline-alley","subtitle":"Moment","details":"The Speedway's historic garage area, where generations of mechanics have prepared 500 cars a few hundred feet from the pits.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f7/Garages_-_2015_Indianapolis_500_-_Sarah_Stierch.jpg/500px-Garages_-_2015_Indianapolis_500_-_Sarah_Stierch.jpg"},{"name":"Indy 500 Rookie of the Year","rarity":"uncommon","id":"indy-500-rookie-of-the-year","subtitle":"Moment","details":"Voted on since 1952, this award honors the outstanding first-year driver in each Indianapolis 500 field.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/36/Fernando_Alonso_2017_Indianapolis_500_1.jpg/500px-Fernando_Alonso_2017_Indianapolis_500_1.jpg"},{"name":"Jacques Villeneuve's '505' Win","rarity":"uncommon","id":"jacques-villeneuve-s-505-win","subtitle":"Moment","details":"Jacques Villeneuve won the 1995 race despite a two-lap penalty, covering 505 miles in the event nicknamed the Indianapolis 505.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cb/Jacques_Villeneuve%27s_Reynard_95I%2C_which_won_the_Indianapolis_500_in_1995._%2855443005936%29.jpg/500px-Jacques_Villeneuve%27s_Reynard_95I%2C_which_won_the_Indianapolis_500_in_1995._%2855443005936%29.jpg"},{"name":"Kissing the Bricks","rarity":"uncommon","id":"kissing-the-bricks","subtitle":"Moment","details":"Dale Jarrett started the brick-kissing celebration at the 1996 Brickyard 400; Gil de Ferran carried it to the 500 in 2003.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ae/Indianapolis_500_-_Kissing_the_brick_%285837422922%29.jpg/500px-Indianapolis_500_-_Kissing_the_brick_%285837422922%29.jpg"},{"name":"Last Row Party","rarity":"uncommon","id":"last-row-party","subtitle":"Moment","details":"Held since 1972, this charity roast dinner celebrates the three slowest qualifiers, the Last Row of each Indy 500 grid.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0a/2017_500_Festival_Parade_-_Drivers_-_Last_row.jpg/500px-2017_500_Festival_Parade_-_Drivers_-_Last_row.jpg"},{"name":"Month of May","rarity":"uncommon","id":"month-of-may","subtitle":"Moment","details":"Indianapolis devotes most of May to the 500, stacking practice, qualifying weekend and Carb Day into a month-long festival.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1a/Indianapolis_Motor_Speedway_%2815982572368%29.jpg/500px-Indianapolis_Motor_Speedway_%2815982572368%29.jpg"},{"name":"Pole Day / Fast Nine Shootout","rarity":"uncommon","id":"pole-day-fast-nine-shootout","subtitle":"Moment","details":"Introduced in 2010, the shootout sent the fastest qualifiers back out for one final run each to settle pole for the 500.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7f/Ed_Carpenter_%282533538131%29.jpg/500px-Ed_Carpenter_%282533538131%29.jpg"},{"name":"Rick Mears's Six Poles","rarity":"uncommon","id":"rick-mears-s-six-poles","subtitle":"Moment","details":"Rick Mears collected a record six Indianapolis 500 pole positions between 1979 and 1991, a mark of one-lap mastery.","image":"https://upload.wikimedia.org/wikipedia/commons/3/36/RickMears1987Indy.jpg"},{"name":"Snake Pit","rarity":"uncommon","id":"snake-pit","subtitle":"Moment","details":"The Turn 3 infield party zone was infamous in the 1970s and was later revived as a race-day concert venue at the Speedway.","image":"https://cdn.ibj.com/wp-content/uploads/2022/05/MJS-20220529_INDY500-0050-1024x681.jpg"},{"name":"Taps","rarity":"uncommon","id":"taps","subtitle":"Moment","details":"Played in pre-race ceremonies, the bugle call Taps honors fallen service members as the 500 anchors Memorial Day weekend.","image":"https://d1ldvf68ux039x.cloudfront.net/thumbs/photos/2405/8439604/1000w_q95.jpg"},{"name":"The 1982 Johncock-Mears Duel","rarity":"uncommon","id":"the-1982-johncock-mears-duel","subtitle":"Moment","details":"Gordon Johncock held off Rick Mears by 0.16 seconds in 1982, in what stood for a decade as the closest finish in 500 history.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/81/Johncockmears1982indy500.JPG/500px-Johncockmears1982indy500.JPG"},{"name":"The 1989 Fittipaldi-Unser Duel","rarity":"uncommon","id":"the-1989-fittipaldi-unser-duel","subtitle":"Moment","details":"In 1989 Emerson Fittipaldi and Al Unser Jr. touched wheels with two laps left; Unser crashed, Fittipaldi won, Unser applauded.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7d/Indy500winningcar1989.JPG/500px-Indy500winningcar1989.JPG"},{"name":"The 2020 Race Behind Closed Gates","rarity":"uncommon","id":"the-2020-race-behind-closed-gates","subtitle":"Moment","details":"Postponed to August and run before empty grandstands in 2020, the 104th Indianapolis 500 was won by Takuma Sato.","image":"https://cdn.ibj.com/wp-content/uploads/2020/08/SATO_wins_2020_Indy_500_1200px-1024x704.jpg"},{"name":"The Pagoda","rarity":"uncommon","id":"the-pagoda","subtitle":"Moment","details":"The towering Pagoda serves as race control above the start-finish line, echoing the wooden original first built in 1913.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e3/Indianapolis_motor_speedway_pagoda%2C_2011.jpg/500px-Indianapolis_motor_speedway_pagoda%2C_2011.jpg"},{"name":"The Turbine's Heartbreak","rarity":"uncommon","id":"the-turbine-s-heartbreak","subtitle":"Moment","details":"Parnelli Jones led 171 of 200 laps in the 1967 STP turbine car, then coasted out with a failed bearing three laps from victory.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/20/Parnelli_Jones_STP_Turbine_%282534457434%29.jpg/500px-Parnelli_Jones_STP_Turbine_%282534457434%29.jpg"},{"name":"Tom Sneva Breaks 200 mph","rarity":"uncommon","id":"tom-sneva-breaks-200-mph","subtitle":"Moment","details":"In 1977 Tom Sneva became the first driver to officially lap Indianapolis beyond 200 mph in qualifying, in the Norton Spirit.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c5/Tomsneva1977car.JPG/500px-Tomsneva1977car.JPG"},{"name":"Triple Crown of Oval Racing","rarity":"uncommon","id":"triple-crown-of-oval-racing","subtitle":"Moment","details":"Indianapolis, Ontario and Pocono formed the 500-mile Triple Crown in 1971-89; a revival ran in 2013-15 with Fontana as third leg.","image":"https://www.autoracing1.com/wp-content/uploads/historic/1975andrettipocono.jpg"},{"name":"Winner's Wreath","rarity":"uncommon","id":"winner-s-wreath","subtitle":"Moment","details":"The winner is draped with a floral wreath in Victory Lane, a post-race ritual of the 500 dating to the early 1960s.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/08/2011_Indy_500_Winner_-_Dan_Wheldon.jpg/500px-2011_Indy_500_Winner_-_Dan_Wheldon.jpg"},{"name":"Buick Indy V6","rarity":"uncommon","id":"buick-indy-v6","subtitle":"Car & Era","details":"The stock-block Buick V6 was a qualifying monster at Indy, taking poles on raw boost while race-day reliability lagged behind.","image":"https://stories.hemmings.com/wp-content/uploads/2024/03/image-11173.jpg"},{"name":"Chevrolet Indy V6","rarity":"uncommon","id":"chevrolet-indy-v6","subtitle":"Car & Era","details":"Chevrolet's twin-turbo V6 arrived with the 2012 formula and ended Honda's run as the series' only engine supplier.","image":"https://www.indycar.com/-/media/IndyCar/News/Standard/2014/03/03-18-Chevrolet-Lifts-Curtain-On-Engine-Std.jpg"},{"name":"Cosworth DFX","rarity":"uncommon","id":"cosworth-dfx","subtitle":"Car & Era","details":"The turbocharged Cosworth V8 powered ten consecutive Indianapolis 500 winners, from 1978 through 1987, a decade of dominance.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b9/Cosworth_DFX_Indy_engine_%281718123039%29.jpg/500px-Cosworth_DFX_Indy_engine_%281718123039%29.jpg"},{"name":"Cummins Diesel Indy Car","rarity":"uncommon","id":"cummins-diesel-indy-car","subtitle":"Car & Era","details":"Fred Agabashian qualified the Cummins Diesel Special on pole for the 1952 Indianapolis 500, a diesel shock at the Brickyard.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fc/Cummins_Diesel_Roadster.jpg/500px-Cummins_Diesel_Roadster.jpg"},{"name":"Dallara IR-05","rarity":"uncommon","id":"dallara-ir-05","subtitle":"Car & Era","details":"The standard IndyCar chassis from 2005 to 2011, the IR-05 era closed with Dan Wheldon's 2011 Indianapolis 500 victory.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5a/KV_Racing_Technology_Dallara-Honda_IR-05%2C_2011_Autosport_Show%2C_NEC_Birmingham%2C_15th_January_%2822717725624%29.jpg/500px-KV_Racing_Technology_Dallara-Honda_IR-05%2C_2011_Autosport_Show%2C_NEC_Birmingham%2C_15th_January_%2822717725624%29.jpg"},{"name":"Ford-Cosworth XB","rarity":"uncommon","id":"ford-cosworth-xb","subtitle":"Car & Era","details":"The DFX's successor powered Ford's final two Indianapolis 500 wins, Jacques Villeneuve in 1995 and Buddy Lazier in 1996.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6b/Indy500winningcar1995.JPG/500px-Indy500winningcar1995.JPG"},{"name":"Honda Indy V8","rarity":"uncommon","id":"honda-indy-v8","subtitle":"Car & Era","details":"Honda's V8 powered nine consecutive Indianapolis 500 winners from 2004 through 2012, a streak spanning two chassis eras.","image":"https://upload.wikimedia.org/wikipedia/commons/6/6c/HondaIndyV8.jpg"},{"name":"Ilmor 265","rarity":"uncommon","id":"ilmor-265","subtitle":"Car & Era","details":"The Ilmor-built Chevrolet V8 powered six straight Indianapolis 500 winners from 1988 to 1993, the heart of the Penske era.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/31/Chevrolet_Indy_V8_%282534375320%29.jpg/500px-Chevrolet_Indy_V8_%282534375320%29.jpg"},{"name":"Lotus 29","rarity":"uncommon","id":"lotus-29","subtitle":"Car & Era","details":"Jim Clark finished second at Indianapolis in 1963 in the Ford-powered Lotus 29, launching the rear-engine challenge in earnest.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/61/Lotus_29_-_1963_Indy_500.jpg/500px-Lotus_29_-_1963_Indy_500.jpg"},{"name":"Lotus 56 Turbine","rarity":"uncommon","id":"lotus-56-turbine","subtitle":"Car & Era","details":"Colin Chapman's wedge-shaped, four-wheel-drive turbine cars headlined the 1968 Indianapolis 500 with their silent whoosh.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7f/Lotus-Pratt_%26_Whitney_Goodwood_2011.jpg/500px-Lotus-Pratt_%26_Whitney_Goodwood_2011.jpg"},{"name":"Novi Engine","rarity":"uncommon","id":"novi-engine","subtitle":"Car & Era","details":"The supercharged Novi V8 was beloved for its scream and qualifying speed at Indy, yet never won the 500 across two decades.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b3/1948_Indy_Novi_Grooved_Piston_Special_%2828918099361%29.jpg/500px-1948_Indy_Novi_Grooved_Piston_Special_%2828918099361%29.jpg"},{"name":"Panoz DP01","rarity":"uncommon","id":"panoz-dp01","subtitle":"Car & Era","details":"Built as Champ Car's spec chassis for 2007, the DP01 served a single season before the series merged into IndyCar in 2008.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/45/Sebastien_Bourdais_2007.jpg/500px-Sebastien_Bourdais_2007.jpg"},{"name":"Penske PC-17","rarity":"uncommon","id":"penske-pc-17","subtitle":"Car & Era","details":"Rick Mears won the 1988 Indianapolis 500 in the brand-new PC-17, Penske's first chassis built around Chevrolet Ilmor power.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/df/Team_Penske_PC-17_1988_Indy_500_Winner_-_Rick_Mears.jpg/500px-Team_Penske_PC-17_1988_Indy_500_Winner_-_Rick_Mears.jpg"},{"name":"Bryan Herta Autosport","rarity":"uncommon","id":"bryan-herta-autosport","subtitle":"Team","details":"Bryan Herta's team won the 500 twice as an underdog operation, with Dan Wheldon in 2011 and Alexander Rossi in 2016.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b3/Bryan_Herta_Autosport_2011_Indy_500_Winner_-_Dan_Wheldon.jpg/500px-Bryan_Herta_Autosport_2011_Indy_500_Winner_-_Dan_Wheldon.jpg"},{"name":"Dale Coyne Racing","rarity":"uncommon","id":"dale-coyne-racing","subtitle":"Team","details":"The paddock's enduring underdog operation waited 25 years for its first win, delivered by Justin Wilson at Watkins Glen in 2009.","image":"https://upload.wikimedia.org/wikipedia/commons/4/48/Dallara-Honda_DW12_Dale_Coyne-Sonnys_Racing_Justin_Wilson_Morning_Practice_Exiting_Turn1_SPGP_24March2012_%2814513048058%29.jpg"},{"name":"Dreyer & Reinbold Racing","rarity":"uncommon","id":"dreyer-reinbold-racing","subtitle":"Team","details":"Founded by former driver Robbie Buhl, the team has been an IndyCar and Indianapolis 500 entrant since 2000.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/42/2010_IZOD_IndyCar_Series_-_S%C3%A3o_Paulo_Indy_300_-_Bia_Figueiredo_Ana_Beatriz_-_Dreyer_%26_Reinbold_Racing_%2826478892364%29.jpg/500px-2010_IZOD_IndyCar_Series_-_S%C3%A3o_Paulo_Indy_300_-_Bia_Figueiredo_Ana_Beatriz_-_Dreyer_%26_Reinbold_Racing_%2826478892364%29.jpg"},{"name":"Ed Carpenter Racing","rarity":"uncommon","id":"ed-carpenter-racing","subtitle":"Team","details":"Indianapolis's hometown team, owned by Ed Carpenter, who won the Indy 500 pole in 2013, 2014 and 2018 as an owner-driver.","image":"https://upload.wikimedia.org/wikipedia/commons/7/7c/Dallara-Chevrolet_DW12_Carpenter-Fuzzys_Racing_Ed_Carpenter_LSideRear_SPGP_24March2012_%2814699419692%29.jpg"},{"name":"Juncos Hollinger Racing","rarity":"uncommon","id":"juncos-hollinger-racing","subtitle":"Team","details":"Ricardo Juncos built his team step by step from karting and the junior ladder all the way to full-time IndyCar competition.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0c/Juncos_Hollinger_Racing_2024_IndyCar_at_Iowa_Speedway_crew.jpg/500px-Juncos_Hollinger_Racing_2024_IndyCar_at_Iowa_Speedway_crew.jpg"},{"name":"KV Racing Technology","rarity":"uncommon","id":"kv-racing-technology","subtitle":"Team","details":"Kevin Kalkhoven and Jimmy Vasser's team won the 2013 Indianapolis 500 with Tony Kanaan, its crowning result before closing in 2016.","image":"https://upload.wikimedia.org/wikipedia/commons/2/26/Dallara-Chevrolet_DW12_KV-Geico_Racing_Tony_Kanaan_LSideRear_Morning_Practice_SPGP_24March2012_%2814513058219%29.jpg"},{"name":"PacWest Racing","rarity":"uncommon","id":"pacwest-racing","subtitle":"Team","details":"A leading CART team of the 1990s, PacWest's banner year was 1997, when Mark Blundell won three races in its colors.","image":"https://www.speedsport-magazine.com/sites/default/files/meldeliste/pacwest-racing-reynard-97i-mercedes-blundell-35390.jpg"},{"name":"Panther Racing","rarity":"uncommon","id":"panther-racing","subtitle":"Team","details":"Panther Racing won back-to-back IRL championships with Sam Hornish Jr. in 2001 and 2002, built around oval mastery.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a3/J._R._Hildebrand_2011_Indy_Japan_300_Warm-up.jpg/500px-J._R._Hildebrand_2011_Indy_Japan_300_Warm-up.jpg"},{"name":"Schmidt Peterson Motorsports","rarity":"uncommon","id":"schmidt-peterson-motorsports","subtitle":"Team","details":"Sam Schmidt's team climbed from Indy Lights to IndyCar wins and poles before evolving into Arrow McLaren SP in 2020.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0b/5_James_Hichcliffe_2018_Kohler_Grand_Prix.jpg/500px-5_James_Hichcliffe_2018_Kohler_Grand_Prix.jpg"},{"name":"Walker Racing","rarity":"uncommon","id":"walker-racing","subtitle":"Team","details":"Derrick Walker's team was a fixture of CART and IRL grids from the early 1990s onward, a durable independent outfit of the CART era.","image":"https://www.speedsport-magazine.com/sites/default/files/meldeliste/walker-racing-reynard-97i-honda-de-ferran-35382.jpg"}]});
